BUILTIN_REFERENCES = frozenset(REFERENCES)
NO_REFERENCE = 'None (do not compare)'
CERTIFICATE_MATERIALS = ('BBOT', 'Methionine', 'Cystine', 'Sulphanilamide')


def certificate_batch_date(name):
    """ISO date of a batch named like 'BN 445356 (13.05.2024)'; '' when the name carries no date."""
    match = re.search(r'\((\d{2})\.(\d{2})\.(\d{4})\)\s*$', str(name or ''))
    return f'{match.group(3)}-{match.group(2)}-{match.group(1)}' if match else ''


def validate_certificate_table(name, table):
    """A batch of certified compositions: {material: {element: % w/w}}; empty cells are allowed."""
    name = re.sub(r'\s+', ' ', str(name or '')).strip()
    if not name or name == NO_REFERENCE:
        raise ValueError('Give the batch its number and date, e.g. BN 445356 (13.05.2024).')
    if len(name) > 80:
        raise ValueError('The batch name is too long (80 characters at most).')
    if not isinstance(table, dict):
        raise ValueError('The certified values must be a table of standards and elements.')
    clean = {}
    for material, values in table.items():
        if material not in CERTIFICATE_MATERIALS:
            raise ValueError(f'Unknown standard material: {material}.')
        if not isinstance(values, dict):
            raise ValueError(f'{material}: the certified values must be given per element.')
        row = {}
        for element, value in values.items():
            if element not in ELEMENTS:
                raise ValueError(f'{material}: unknown element {element}.')
            if value is None or value == '':
                continue
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or not 0 < value < 100:
                raise ValueError(f'{material} {element}: a certified value must be a percentage between 0 and 100.')
            row[element] = round(float(value), 4)
        if row:
            clean[material] = row
    if not clean:
        raise ValueError('Enter at least one certified value.')
    return name, clean


def register_certificates(tables):
    """Batches entered by the user (kept with the project and in the user's settings) join the built-in labels.
    The built-in label values cannot be redefined."""
    for name, table in (tables or {}).items():
        try:
            name, clean = validate_certificate_table(name, table)
        except ValueError:
            continue
        if name not in BUILTIN_REFERENCES and name not in REFERENCES:
            REFERENCES[name] = clean  # the list of choices only; a project reads its own stored values


def project_certificates(project):
    return dict(((getattr(project, 'processing', None) or {}).get('certificates') or {}))


def reference_values(project, name=None):
    """The certified values of a batch for this project: a built-in label, else the copy stored with the project,
    else the batch list of this computer (a batch just chosen; it is stored with the project at once)."""
    name = project.settings.reference_table if name is None else name
    if name in BUILTIN_REFERENCES:
        return REFERENCES[name]
    stored = project_certificates(project).get(name)
    if stored:
        return stored
    return REFERENCES.get(name) or {}


def _store_project_certificate(project, name):
    """A user batch chosen for a project is copied into it, so the project file stands alone."""
    if name in BUILTIN_REFERENCES or name == NO_REFERENCE or name not in REFERENCES:
        return
    if not isinstance(getattr(project, 'processing', None), dict):
        project.processing = {}
    certificates = project.processing.setdefault('certificates', {})
    if name not in certificates:
        certificates[name] = copy.deepcopy(REFERENCES[name])


def save_project_certificate(project, name, table):
    """Store a user batch with the project (so the project file stands alone) and make it selectable."""
    name, clean = validate_certificate_table(name, table)
    if name in BUILTIN_REFERENCES:
        raise ValueError('This batch is built in from the bottle label; give the new batch another number or date.')
    if not isinstance(getattr(project, 'processing', None), dict):
        project.processing = {}
    previous = (project.processing.get('certificates') or {}).get(name)
    project.processing.setdefault('certificates', {})[name] = clean
    REFERENCES[name] = clean
    if previous != clean:
        project.decisions.append({'time_utc': utc_now(), 'action': 'certificate_values_saved',
                                  'batch': name, 'values': copy.deepcopy(clean)})
    return name


def default_check_reference(project):
    """The batch most likely in use: the newest batch dated on or before the first measurement of the run.
    Only a proposal — the label of the bottle in use decides, and the batch can be changed in steps 3 and 4."""
    dates = sorted(str(getattr(r, 'date', '') or '')[:10] for r in project.records
                   if re.match(r'^\d{4}-\d{2}-\d{2}', str(getattr(r, 'date', '') or '')))
    batches = sorted((certificate_batch_date(n), n) for n in REFERENCES if certificate_batch_date(n))
    if not batches:
        return NO_REFERENCE
    if not dates:
        return batches[-1][1]
    before = [b for b in batches if b[0] <= dates[0]]
    return before[-1][1] if before else NO_REFERENCE


def check_material_results(project, preview, element):
    """Each check material's result with the current calibration against its certified value
    (the batch chosen as comparison reference). Nothing is judged: no laboratory tolerance is assumed."""
    batch = project.settings.reference_table
    table = reference_values(project, batch)
    records = ((preview or {}).get('records') or {})
    out = []
    for record in project.records:
        if record.role != 'Check':
            continue
        material = check_material(record.name) or check_material(record.group)
        item = ((records.get(str(record.index)) or {}).get('elements') or {}).get(element) or {}
        found = item.get('value')
        found = float(found) if _finite_percentage(found) else None
        certified = (table.get(material) or {}).get(element)
        certified = float(certified) if isinstance(certified, (int, float)) and not isinstance(certified, bool) and certified > 0 else None
        out.append({'index': record.index, 'name': record.name, 'material': material, 'batch': batch,
                    'found': found, 'certified': certified,
                    'difference': found - certified if found is not None and certified is not None else None,
                    'recovery': 100 * found / certified if found is not None and certified is not None else None})
    return out


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec='seconds')


def tidy(x) -> str:
    return re.sub(r'\s+', ' ', unicodedata.normalize('NFKC', str(x or ''))).strip()


def key(x) -> str:
    return tidy(x).casefold()


def filename_safe(x: str) -> str:
    return (re.sub(r'[^\w .()+-]', '_', tidy(x)).strip(' ._') or 'CHNS run')[:90]


def optional_number(value, *, decimal='auto') -> Optional[float]:
    if value is None or value == '' or (isinstance(value, str) and not value.strip()):
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, (int,float)):
        return float(value) if math.isfinite(float(value)) else None
    text = unicodedata.normalize('NFKC', str(value)).strip().replace('−','-')
    if any(c in text for c in '<>~='):
        return None  # preserve censored/invalid inputs as missing, never zero
    text = text.replace('\xa0','').replace(' ', '')
    if decimal == 'dot':
        if ',' in text and not re.fullmatch(r'[+-]?\d{1,3}(?:,\d{3})+(?:\.\d*)?', text):
            return None
        text = text.replace(',','')
    elif decimal == 'comma':
        if '.' in text and not re.fullmatch(r'[+-]?\d{1,3}(?:\.\d{3})+(?:,\d*)?',text):
            return None
        text=text.replace('.','').replace(',','.')
    else:
        if ',' in text and '.' in text:
            text = text.replace(',','') if text.rfind('.')>text.rfind(',') else text.replace('.','').replace(',','.')
        elif ',' in text:
            # 1,234 is ambiguous: don't silently interpret as 1.234 or 1234.
            if re.fullmatch(r'[1-9]\d{0,2},\d{3}',text): return None
            text = text.replace(',','.')
    try:
        out = float(text)
        return out if math.isfinite(out) else None
    except ValueError:
        return None


def unique_output_folder(parent, run_name):
    parent = Path(parent).expanduser().resolve()
    parent.mkdir(parents=True,exist_ok=True)
    root = filename_safe(run_name) + ' - CHNSetti ' + datetime.now().strftime('%Y-%m-%d')
    for i in range(1,10000):
        folder=parent/(root if i==1 else f'{root} ({i})')
        try:
            folder.mkdir()
            return folder
        except FileExistsError:
            continue
    raise ValueError('No unused output folder available.')


def safe_cell(value):
    """Prevent user-entered labels being interpreted as formulae by Excel."""
    if isinstance(value, str) and value.startswith(('=', '+', '-', '@', '\t', '\r')):
        return "'" + value
    return value


def file_hash(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


