# ------------------------ spreadsheet reading -------------------------------
# XLS fallback: bounded, read-only BIFF8 reader derived from Plasmatti GPL-3.0.
# xlrd is preferred for .xls when installed; the fallback reads *cached* formula
# results only, without executing macros or evaluating formulas.

@dataclass
class LegacySheet:
    name: str
    cells: dict = field(default_factory=dict)
    nrows: int = 0
    ncols: int = 0
    def put(self, r,c,v):
        self.nrows = max(self.nrows,r+1)
        self.ncols = max(self.ncols,c+1)
        if v is not None and v!='': self.cells[r,c]=v
    def row(self,r):
        return [self.cells.get((r,c),'') for c in range(self.ncols)]


def _u16(b,o=0): return struct.unpack_from('<H',b,o)[0]
def _u32(b,o=0): return struct.unpack_from('<I',b,o)[0]


def _ole_stream(data):
    if len(data)<512 or data[:8]!=bytes.fromhex('D0CF11E0A1B11AE1'):
        raise ValueError('Not a classic .XLS compound document.')
    sector_size=1<<_u16(data,30);mini=1<<_u16(data,32)
    if sector_size not in (512,4096) or mini!=64:
        raise ValueError('Unrecognized XLS container sector sizes.')
    n=(len(data)//sector_size)-1
    def sector(i):
        if not 0<=i<n:raise ValueError('Invalid sector chain (possibly damaged XLS file).')
        return data[(i+1)*sector_size:(i+2)*sector_size]
    difat=list(struct.unpack_from('<109I',data,76));sid=_u32(data,68)
    seen=set()
    for _ in range(min(_u32(data,72),n)):
        if sid in seen:raise ValueError('Cyclic XLS DIFAT.')
        seen.add(sid);buf=sector(sid)
        difat+=list(struct.unpack('<'+str(sector_size//4-1)+'I',buf[:-4]));sid=_u32(buf,sector_size-4)
    fat=[]
    for i in [v for v in difat if v<0xFFFFFFFA][:_u32(data,44)]:
        fat+=list(struct.unpack('<'+str(sector_size//4)+'I',sector(i)))
    def chain(start,table,get,limit):
        blocks=[];seen=set();i=start
        while i<0xFFFFFFFA:
            if i in seen or i>=len(table) or len(seen)>limit:
                raise ValueError('Invalid/cyclic XLS sector chain.')
            seen.add(i);blocks.append(get(i));i=table[i]
        return b''.join(blocks)
    directory=chain(_u32(data,48),fat,sector,n)
    root=None;entry=None
    for o in range(0,len(directory)-127,128):
        d=directory[o:o+128];s=_u16(d,64)
        if not 2<=s<=64:continue
        nm=d[:s-2].decode('utf-16le',errors='replace').lower()
        if d[66]==5:root=d
        if d[66]==2 and nm in ('workbook','book'):entry=d
    if entry is None:raise ValueError('XLS workbook stream missing.')
    length=struct.unpack_from('<Q',entry,120)[0];start=_u32(entry,116)
    if length>MAX_INPUT_BYTES:raise ValueError('XLS stream exceeds safety limit.')
    if length>=_u32(data,56):return chain(start,fat,sector,n)[:length]
    if root is None:raise ValueError('XLS mini-stream root missing.')
    pool=chain(_u32(root,116),fat,sector,n)
    mini_fat=chain(_u32(data,60),fat,sector,n)
    minifat=list(struct.unpack('<'+str(len(mini_fat)//4)+'I',mini_fat))
    def mini_sector(i):
        if (i+1)*mini>len(pool):raise ValueError('Invalid XLS mini-sector.')
        return pool[i*mini:(i+1)*mini]
    return chain(start,minifat,mini_sector,len(minifat))[:length]


class _Segments:
    def __init__(self,segments):self.parts=segments;self.i=0;self.p=0
    def rem(self):return len(self.parts[self.i])-self.p
    def advance(self):
        self.i+=1;self.p=0
        if self.i>=len(self.parts):raise ValueError('Truncated XLS shared string.')
    def read(self,n):
        chunks=[]
        while n:
            if not self.rem():self.advance()
            length=min(n,self.rem());chunks.append(self.parts[self.i][self.p:self.p+length]);self.p+=length;n-=length
        return b''.join(chunks)
    def string(self,short=False):
        chars=int.from_bytes(self.read(1 if short else 2),'little');flags=self.read(1)[0]
        runs=int.from_bytes(self.read(2),'little') if flags&8 else 0
        ext=int.from_bytes(self.read(4),'little') if flags&4 else 0
        wide=bool(flags&1);parts=[]
        while chars:
            if not self.rem():
                self.advance();wide=bool(self.read(1)[0]&1)
            w=2 if wide else 1;k=min(chars,self.rem()//w)
            if not k:raise ValueError('Unsupported split Unicode character in XLS.')
            parts.append(self.read(k*w).decode('utf-16le' if wide else 'latin1'));chars-=k
        if runs:self.read(runs*4)
        if ext:self.read(ext)
        return ''.join(parts)


def _biff_records(data):
    pos=0
    while pos+4<=len(data):
        ident,size=struct.unpack_from('<HH',data,pos)
        if pos+4+size>len(data):raise ValueError('Truncated XLS record.')
        yield pos,ident,data[pos+4:pos+4+size]
        pos+=4+size


def _rk(n):
    if n&2:v=struct.unpack('<i',struct.pack('<I',n))[0]>>2
    else:v=struct.unpack('<d',struct.pack('<II',0,n&0xFFFFFFFC))[0]
    return v/100 if n&1 else v


def read_legacy_xls(raw):
    try:
        import xlrd  # optional, supports more XLS variants
        try:
            book=xlrd.open_workbook(file_contents=raw,on_demand=True)
            try:
                return [(s.name,[s.row_values(r) for r in range(s.nrows)]) for s in book.sheets()]
            finally:book.release_resources()
        except Exception:
            # Eager 300 has some physical XLS files with a short final sector.
            # Try the bounded, read-only fallback before rejecting the file.
            pass
    except ImportError:
        pass
    # Several genuine Eager 300 XLS exports end with a short physical sector.
    # Read-only zero-padding restores the documented 512-byte OLE sector frame.
    # All internal sector chains/records are still validated.
    if len(raw)%512:
        raw=raw + b'\x00' * (-len(raw)%512)
    stream=_ole_stream(raw);records=list(_biff_records(stream));bounds=[];shared=[]
    if not records or records[0][1]!=0x809 or _u16(records[0][2])!=0x600:
        raise ValueError('Unsupported XLS version. Install xlrd for older workbooks.')
    for i,(off,k,b) in enumerate(records):
        if k==0x2F:raise ValueError('Encrypted XLS is not supported.')
        if k==0x85 and len(b)>=7 and b[5]==0:
            bounds.append((_u32(b),_Segments([b[6:]]).string(short=True)))
        if k==0xFC:
            parts=[b];j=i+1
            while j<len(records) and records[j][1]==0x3C:
                parts.append(records[j][2]);j+=1
            st=_Segments(parts);st.read(4);unique=_u32(st.read(4))
            if unique>1_000_000:raise ValueError('Unreasonably large XLS string table.')
            shared=[st.string() for _ in range(unique)]
    offsets={o:i for i,(o,_,_) in enumerate(records)};sheets=[]
    errors={0:'#NULL!',7:'#DIV/0!',15:'#VALUE!',23:'#REF!',29:'#NAME?',36:'#NUM!',42:'#N/A'}
    for off,name in bounds:
        if off not in offsets:raise ValueError('Corrupt XLS worksheet offset.')
        s=LegacySheet(name);pending=None
        for _,k,b in records[offsets[off]+1:]:
            if k==0x0A:break
            if k in (0xFD,0x203,0x27E,0x205,0x204,6):
                r,c=_u16(b),_u16(b,2)
                if r>150_000 or c>1000:raise ValueError('XLS sheet too large.')
                if k==0xFD:v=shared[_u32(b,6)]
                elif k==0x203:v=struct.unpack_from('<d',b,6)[0]
                elif k==0x27E:v=_rk(_u32(b,6))
                elif k==0x205:v=errors.get(b[6],'#ERROR') if b[7] else bool(b[6])
                elif k==0x204:v=_Segments([b[6:]]).string()
                else:
                    if b[12:14]==b'\xff\xff':
                        v=None
                        if b[6]==0:pending=(r,c)
                        elif b[6]==1:v=bool(b[8])
                        elif b[6]==2:v=errors.get(b[8],'#ERROR')
                    else:v=struct.unpack_from('<d',b,6)[0]
                s.put(r,c,v)
            elif k==0xBD:
                r,c=_u16(b),_u16(b,2)
                for o in range(4,len(b)-2,6):s.put(r,c,_rk(_u32(b,o+2)));c+=1
            elif k==0x207 and pending is not None:
                s.put(*pending,_Segments([b]).string());pending=None
        sheets.append((name,[s.row(r) for r in range(s.nrows)]))
    if not sheets:raise ValueError('No recognizable worksheets in XLS.')
    return sheets


def read_sheets(raw:bytes,filename:str):
    """Read-only; only stored/cached values are loaded; never execute macros."""
    if len(raw)>MAX_INPUT_BYTES:raise ValueError('File larger than 50 MB safety limit.')
    if raw[:8]==bytes.fromhex('D0CF11E0A1B11AE1'):
        return read_legacy_xls(raw)
    if raw[:2]==b'PK':
        try:
            from openpyxl import load_workbook
        except ImportError as exc:
            raise RuntimeError('XLSX support requires: pip install openpyxl') from exc
        wb=load_workbook(io.BytesIO(raw),read_only=True,data_only=True)
        try:
            return [(sh.title,[list(row) for row in sh.iter_rows(values_only=True)]) for sh in wb.worksheets]
        finally:wb.close()
    if Path(filename).suffix.lower() in ('.csv','.tsv','.txt'):
        text=None
        for enc in ('utf-8-sig','utf-16','cp1252'):
            try:text=raw.decode(enc);break
            except UnicodeDecodeError:pass
        if text is None:raise ValueError('Cannot decode text export.')
        sniffer=text[:10000]
        delimiter='\t' if '\t' in sniffer.splitlines()[0] else (';' if sniffer.count(';')>sniffer.count(',') else ',')
        return [('CSV',[list(r) for r in csv.reader(io.StringIO(text), delimiter=delimiter)])]
    raise ValueError('Not a supported XLS/XLSX/CSV file.')


def member_is_safe(name):
    p=PurePosixPath(name.replace('\\','/'))
    return not(p.is_absolute() or '..' in p.parts or any(':' in x for x in p.parts))


def archive_entries(path):
    """Safe, useful entry points for one run inside a ZIP: methods preferred.

    A paired SUM appears automatically when its MTH is selected; if no MTH exists,
    SUM is listed as a standalone source. Excel/CSV options remain available.
    """
    with zipfile.ZipFile(path) as z:
        info=z.infolist()
        if len(info)>MAX_ZIP_MEMBERS:raise ValueError('Archive has too many entries.')
        valid=[x.filename for x in info if not x.is_dir() and member_is_safe(x.filename)
               and x.filename.lower().endswith(('.mth','.sum','.xls','.xlsx','.csv','.tsv'))
               and not PurePosixPath(x.filename).name.startswith(('._','~$'))
               and x.file_size<=MAX_INPUT_BYTES]
    methods={n.lower()[:-4] for n in valid if n.lower().endswith('.mth')}
    choices=[n for n in valid if not (n.lower().endswith('.sum') and n.lower()[:-4] in methods)]
    return sorted(choices,key=lambda n:(0 if n.lower().endswith('.mth') else 1,n.lower()))


def source_bytes(path, member=None):
    if member is not None:
        if not member_is_safe(member):raise ValueError('Unsafe archive entry name.')
        with zipfile.ZipFile(path) as z:
            if len(z.infolist())>MAX_ZIP_MEMBERS:raise ValueError('Archive has too many entries.')
            info=z.getinfo(member)
            if info.is_dir():raise ValueError('An archive directory is not a data file.')
            if info.file_size>MAX_INPUT_BYTES:raise ValueError('Archive entry exceeds 50 MB limit.')
            return z.read(info),f'{Path(path).name} :: {member}'
    p=Path(path)
    if p.stat().st_size>MAX_INPUT_BYTES:raise ValueError('Input exceeds 50 MB limit.')
    return p.read_bytes(),str(p)


class MissingCompanionError(ValueError):
    """An MTH method was chosen but its SUM results file was not found."""


def _matching_partner(path, extension, *, member=None):
    """Find same-folder/same-stem companion, strictly (never another run)."""
    if member is None:
        path=Path(path)
        matches=[p for p in path.parent.iterdir() if p.is_file() and p.suffix.casefold()==extension
                 and p.stem.casefold()==path.stem.casefold()]
        if len(matches)>1:raise ValueError('More than one companion '+extension+' was found; select an unambiguous run.')
        return str(matches[0]) if matches else None
    with zipfile.ZipFile(path) as z:
        members=[x.filename for x in z.infolist() if not x.is_dir() and member_is_safe(x.filename)
                 and x.file_size<=MAX_INPUT_BYTES]
    target=member[:-len(Path(member).suffix)].casefold()+extension
    matches=[n for n in members if n.casefold()==target]
    if len(matches)>1:raise ValueError('Duplicate companion files found in archive.')
    return matches[0] if matches else None


def _find_run_source_folder(path):
    """Only examine this folder, never recurse into a different experiment."""
    directory=Path(path)
    methods=sorted((p for p in directory.iterdir() if p.is_file() and p.suffix.lower()=='.mth'),key=str)
    summaries=sorted((p for p in directory.iterdir() if p.is_file() and p.suffix.lower()=='.sum'),key=str)
    if len(methods)==1:return methods[0]
    if len(methods)>1:raise ValueError('Folder contains multiple .MTH methods; select the intended .MTH file directly.')
    if len(summaries)==1:return summaries[0]
    if len(summaries)>1:raise ValueError('Folder contains multiple .SUM files; select the intended .SUM file directly.')
    raise ValueError('No .MTH or .SUM file found in the selected folder.')


def _native_string(field: bytes) -> str:
    return field.split(b'\x00',1)[0].decode('cp1252',errors='replace').strip()


def parse_native_sum(raw: bytes):
    """Read the fixed-record Eager 300 .SUM format observed in 68 lab runs.

    Observed binary structure (little-endian; bytes relative to each record):
      record length: 1058
      0: 0x017b 0x0004; 4: 1-based sequence; 6: type (0 bypass, 1 STD, 2 UNK)
      8: name [128]; 136: data filename [128]; 264: date/time [16]
      280: float32 sample mass in mg; 284: protein factor (not a CHNS correction)
      588: float32 nitrogen, 592: carbon, 596: hydrogen, 600: sulfur (% w/w)

    Strict format checks prevent other binary inputs being silently misinterpreted.
    """
    if not raw or len(raw)>MAX_INPUT_BYTES or len(raw)%NATIVE_SUM_RECORD_BYTES:
        raise ValueError('Invalid Eager 300 .SUM length; expected complete 1,058-byte records.')
    if len(raw)//NATIVE_SUM_RECORD_BYTES>10000:
        raise ValueError('Implausible number of CHNS records.')
    records=[]
    for idx in range(len(raw)//NATIVE_SUM_RECORD_BYTES):
        base=idx*NATIVE_SUM_RECORD_BYTES
        record=memoryview(raw)[base:base+NATIVE_SUM_RECORD_BYTES]
        if bytes(record[:4])!=NATIVE_SUM_PREFIX:
            raise ValueError(f'.SUM record {idx+1} does not have the expected Eager 300 signature.')
        ordinal,kind=struct.unpack_from('<HH',record,4)
        if ordinal!=idx+1 or kind not in (0,1,2):
            raise ValueError(f'.SUM record {idx+1} has an unexpected number or instrument type.')
        name=_native_string(bytes(record[8:136]))
        file_id=_native_string(bytes(record[136:264]))
        dt=_native_string(bytes(record[264:280]))
        if not name:
            raise ValueError(f'.SUM record {idx+1} has an empty sample identity.')
        weight=struct.unpack_from('<f',record,280)[0]
        if not math.isfinite(weight):weight=None
        vals=struct.unpack_from('<ffff',record,588)
        values={e:(float(v) if math.isfinite(v) else None) for e,v in zip(ELEMENTS,vals)}
        # The date/time field is normally DD-MM-YYHH:MM; retain other variants verbatim.
        date=dt;time=''
        matched=re.fullmatch(r'(\d{2})-(\d{2})-(\d{2})(\d{2}:\d{2})',dt)
        if matched:
            day,month,yr,time=matched.groups()
            year=2000+int(yr) if int(yr)<=79 else 1900+int(yr)
            date=f'{year:04d}-{month}-{day}'
        kind_name={0:'By-Pass',1:'STD',2:'UNK'}[kind]
        notes=['Read from the saved native Eager 300 .SUM summary; verify against final integration/export.']
        if kind==1:
            notes.append('STD percentages are assigned calibration values, not independent QC results.')
        records.append(Measurement(idx+1,name,file_id,date,time,kind_name,weight,values,
                                   source_row=idx+1,notes=notes))
    return records


def _file_manifest(role,origin,raw):
    return {'role':role,'name':origin,'sha256':file_hash(raw),'bytes':len(raw)}


def project_from_native(sum_raw,sum_source,*,mth_raw=None,mth_source=None,run_name=''):
    records=parse_native_sum(sum_raw)
    guesses=guess_roles(records)
    manifest=[_file_manifest('SUM results',sum_source,sum_raw)]
    warnings=[
        'NATIVE RESULTS — ANALYST VERIFICATION REQUIRED. The .SUM file contains saved Eager 300 CHNS '
        'percentages and stored sample types, which may NOT reflect the engineer\'s final reviewed/reintegrated '
        'chromatograms and sample classifications. Compare with the final Eager 300 export before reporting.',
        'CHNSetti reads instrument-calculated percentages and calculates replicate statistics; '
        'it does not read .DAT chromatograms, reintegrate peaks or recalibrate the instrument.',
    ]
    if mth_raw is not None:
        if len(mth_raw)<100 or len(mth_raw)>MAX_INPUT_BYTES:
            raise ValueError('Invalid or oversized .MTH method file.')
        manifest.insert(0,_file_manifest('MTH method',mth_source or 'Method (.MTH)',mth_raw))
        if not all(el in mth_raw for el in (b'Nitrogen',b'Carbon',b'Hydrogen',b'Sulphur')):
            raise ValueError('The selected .MTH does not appear to describe a CHNS Eager 300 method.')
        ids=[r.file_id.encode('cp1252',errors='replace') for r in records if r.file_id]
        unmatched=[r.name for r in records if r.file_id and r.file_id.encode('cp1252',errors='replace') not in mth_raw]
        if ids and (len(ids)-len(unmatched))/len(ids)<0.50:
            raise ValueError('The .MTH and .SUM sample sequences disagree substantially. '
                             'They may be from different sessions; please select a matching pair.')
        if unmatched:
            warnings.append(f'Method/summary check: {len(unmatched)} of {len(ids)} saved file identifiers '
                            'were not found in the method. This may reflect edits made after method setup; '
                            'verify that the files belong to the same run.')
    else:
        warnings.append('The matching .MTH method was not supplied. This import uses .SUM only; '
                        'calibration/method metadata cannot be cross-checked.')
    invalid=sum(any(v is not None and (v<0 or v>100) for v in r.values.values()) for r in guesses)
    if invalid:
        warnings.append(f'{invalid} measurement(s) contain an element outside 0–100% and require review.')
    status='Eager 300 native .MTH + .SUM (provisional)' if mth_raw is not None else 'Eager 300 native .SUM (provisional)'
    # SUM hash identifies the exact instrument percentages used; MTH hash is in manifest.
    label=(mth_source+' + '+sum_source) if mth_source else sum_source
    suggested=Path(mth_source or sum_source).parent.name
    name=run_name or (suggested if suggested and suggested not in ('.','') and '::' not in suggested else 'CHNS native run')
    return Project(records=guesses,settings=Settings(run_name=name),input_format=status,
                   source_name=label,source_sha256=file_hash(sum_raw),source_files=manifest,
                   input_warnings=warnings)


# ------------------------ format recognition and import ----------------------

def parse_instrument_type(x):
    t=key(x).replace(' ','').replace('_','').replace('-','')
    return ('Bypass' if t.startswith('bypass') else 'Calibration' if t in ('std','standard')
            else 'Unknown' if t in ('unk','unknown','sample') else '')


def check_material(name):
    token = re.sub(r'[^a-z0-9]+', '', key(name))
    aliases = {
        'BBOT': ('bbot',),
        'Methionine': ('methionine', 'meth'),
        'Cystine': ('cystine', 'cyst'),
        'Sulphanilamide': ('sulphanilamide', 'sulfanilamide', 'sulfanilimide',
                          'sulfanilimid', 'sulfanimid', 'sulphanilimide', 'sulphanilimid'),
    }
    for material, forms in aliases.items():
        if token in forms or (token.startswith(material.lower()) and len(token) < len(material) + 2):
            return material
    return ''


REPLICATE_SUFFIX=re.compile(r'^(.*?)\s*(?:\s-\s*|\s*_\s*|\s+)(\d{1,2})\s*$',re.UNICODE)


def sample_group_name(name):
    """Accept delimited replicate suffixes such as 'Sample 1-1' or 'Demo A - 2'; a name such as 'N1' stays whole."""
    value = tidy(name)
    matched = re.fullmatch(r'(.*?)(?:\s*[-_]\s*|\s+)(\d{1,2})', value)
    if matched and matched[1].strip() and 1 <= int(matched[2]) <= 20:
        return matched[1].strip()
    return value


def guess_roles(records):
    """Instrument type wins; a known reference as UNK is a CHECK, not calibration."""
    prior=[]
    for r in records:
        typ=parse_instrument_type(r.instrument_type)
        if typ=='Bypass' or key(r.name).startswith('bypass'):
            r.role='Bypass';r.group='';continue
        if typ=='Calibration':
            r.role='Calibration';r.group=check_material(r.name) or r.name;continue
        material=check_material(r.name)
        if material:
            r.role='Check';r.group=material;continue
        r.role='Sample'
        name=sample_group_name(r.name)
        # A repeated sample name in two nonadjacent blocks is not silently merged.
        if prior and prior[-1][0] == key(name):
            r.group=prior[-1][1]
        else:
            same_count=sum(k==key(name) for k,g in prior if k!='')
            # Only create a new group when a former group of that name was separated.
            old=[g for k,g in prior if k==key(name)]
            r.group=(name if not old else name+' [block '+str(len(set(old))+1)+']')
        prior.append((key(name),r.group))
    return records


def _str(row,i):
    return tidy(row[i]) if i<len(row) else ''


def _val(row,i):
    return optional_number(row[i]) if i<len(row) else None


def parse_native_headerless(rows):
    """The observed native 15-col Eager 300 'Summarize results -> Excel' layout."""
    valid=[]
    for i,row in enumerate(rows):
        if len(row)>=15 and _str(row,1) and parse_instrument_type(_str(row,5)):
            valid.append(i)
    if len(valid)<2 or len(valid)<max(2,len([r for r in rows if len(r)>=15])//3):
        return None
    out=[]
    for idx in valid:
        row=rows[idx];name=_str(row,1)
        kind=_str(row,5)
        mass=_val(row,6)
        values={el:_val(row,11+j) for j,el in enumerate(ELEMENTS)}
        notes=[]
        if parse_instrument_type(kind)=='Calibration':
            notes.append('STD row: element percentages may be assigned calibration concentrations, not a measured QC result.')
        out.append(Measurement(len(out)+1,name,_str(row,2),_str(row,3),_str(row,4),kind,mass,
                               values,source_row=idx+1,notes=notes))
    return out


def header_map(row):
    """Recognize a labelled export, with any element ordering."""
    labels=[key(v) for v in row]
    columns={}
    for i,v in enumerate(labels):
        normal=re.sub(r'[^a-z0-9]','',v)
        if normal in ('samplename','sampleid','sample') and 'name' not in columns:columns['name']=i
        elif normal in ('filename','fileid','datafilename'):columns['file_id']=i
        elif normal in ('type','sampletype','kind'):columns['type']=i
        elif normal in ('weightmg','massmg','sampleweightmg','samplemassmg'):columns['weight']=i
        elif normal in ('date','injectiondate','injdate'):columns['date']=i
        elif normal in ('time','injectiontime','injtime'):columns['time']=i
        elif normal in ('nitrogen','nitrogenww','nitrogenpct','nww','npercent','n'):columns['N']=i
        elif normal in ('carbon','carbonww','carbonpct','cww','cpercent','c'):columns['C']=i
        elif normal in ('hydrogen','hydrogenww','hydrogenpct','hww','hpercent','h'):columns['H']=i
        elif normal in ('sulfur','sulphur','sulfurww','sulphurww','sulfurpct','sulphurpct','sww','spercent','s'):columns['S']=i
    return columns


def parse_native_with_header(rows):
    for start,row in enumerate(rows[:35]):
        h=header_map(row)
        if 'name' not in h or len(set(ELEMENTS)&set(h))<3:continue
        out=[]
        for idx in range(start+1,len(rows)):
            raw=rows[idx];name=_str(raw,h['name'])
            if not name or key(name) in ('sample','sample name'):continue
            role=_str(raw,h['type']) if 'type' in h else 'UNK'
            if 'type' in h and not parse_instrument_type(role):continue
            vals={e:_val(raw,h[e]) if e in h else None for e in ELEMENTS}
            # Preserve a named, failed acquisition with all elements missing.
            # It becomes a review item instead of disappearing from the run.
            mass=_val(raw,h['weight']) if 'weight' in h else None
            out.append(Measurement(len(out)+1,name,_str(raw,h['file_id']) if 'file_id' in h else '',
                                   _str(raw,h['date']) if 'date' in h else '',
                                   _str(raw,h['time']) if 'time' in h else '',role,mass,
                                   vals,source_row=idx+1))
        if out:return out
    return None


def _historical_group_label(names):
    """Use group boundaries written in the historical report, not a guessed suffix."""
    if len(names)==1:return sample_group_name(names[0])
    import os as _os
    prefix=_os.path.commonprefix(names)
    suffix=_os.path.commonprefix([n[::-1] for n in names])[::-1]
    candidate=(prefix.rstrip(' -_')+' '+suffix.lstrip(' -_')).strip()
    candidate=re.sub(r'\s+',' ',candidate)
    if len(candidate)<1 or key(candidate) in ('sample','-'):
        return sample_group_name(names[0])
    return candidate


def parse_completed_report(rows):
    """Read original report rows and explicit group boundaries, retaining sources."""
    summaries = ('avg', 'avg.', 'stdev', 'stdev.', 'average', 'std', 'sd')
    for start, row in enumerate(rows[:20]):
        heads = [key(value) for value in row]
        if 'sample' not in heads or not any('(mg)' in value for value in heads):
            continue
        sample_column = heads.index('sample')
        weight_column = next(i for i, value in enumerate(heads) if '(mg)' in value)
        element_columns = {}
        for column in range(max(len(row), 8)):
            combined = ' '.join(_str(rows[r], column).lower() for r in range(max(0, start - 2), start + 1))
            for element, label in NAMES.items():
                if label.lower() in combined or (element == 'S' and 'sulphur' in combined):
                    element_columns[element] = column
        if len(element_columns) < 3:
            continue
        # A normal one-row labelled export can also contain Sample, Weight (mg),
        # and full element names. It has no report block boundaries: treating it
        # as a completed report would merge unrelated samples into one group.
        # The observed archive layout has a separate '(mg)' units row beneath
        # the element labels. Otherwise require an explicit summary row with no
        # sample mass before applying historical-report grouping rules.
        unit_header = re.sub(r'\s+', '', heads[weight_column]) == '(mg)'
        preceding_elements = 0
        for element, column in element_columns.items():
            preceding = ' '.join(_str(rows[r], column).lower()
                                 for r in range(max(0, start - 2), start))
            if NAMES[element].lower() in preceding or (element == 'S' and 'sulphur' in preceding):
                preceding_elements += 1
        archival_units_layout = unit_header and preceding_elements >= 3
        explicit_summary = any(
            _val(candidate, weight_column) is None
            and (not _str(candidate, sample_column) or key(_str(candidate, sample_column)) in summaries)
            and any(key(value) in summaries for value in candidate if isinstance(value, str))
            for candidate in rows[start + 1:]
        )
        if not archival_units_layout and not explicit_summary:
            continue
        output, block = [], []

        def commit():
            if not block:
                return
            label = _historical_group_label([r.name for r in block])
            used = {r.group for r in output}
            if label in used:
                number = 2
                while f'{label} [block {number}]' in used:
                    number += 1
                label = f'{label} [block {number}]'
            for record in block:
                record.group, record.role = label, 'Sample'
                output.append(record)
            block.clear()

        for row_index in range(start + 1, len(rows)):
            source = rows[row_index]
            name = _str(source, sample_column)
            if any(key(value) in summaries for value in source if isinstance(value, str)):
                commit()
                continue
            if not name or key(name) in summaries:
                commit()
                continue
            if re.search(r'\b(?:LOQ|LOD|limit of|detection limit)\b', name, re.I):
                continue
            mass_column = weight_column
            mass = _val(source, mass_column)
            # Archived reports sometimes place the weight in D while C is blank.
            # Restrict the correction to that observed C/D layout and numeric D.
            if weight_column == 2 and _str(source, 2) == '' and 3 not in element_columns.values() and _val(source, 3) is not None:
                mass_column, mass = 3, _val(source, 3)
            values = {element: _val(source, element_columns[element]) if element in element_columns else None
                      for element in ELEMENTS}
            has_original_text = any(_str(source, col) for col in element_columns.values())
            if not has_original_text and mass is None:
                continue
            record = Measurement(0, name, '', '', '', 'UNK', mass, values,
                                 source_row=row_index + 1,
                                 notes=['Original entry in a finished report; its provenance may include manual processing.'])
            _attach_source_columns(record, source,
                                   {'name': sample_column, 'weight_mg': mass_column, **element_columns})
            if mass_column != weight_column:
                record.notes.append('Weight read from column D because the original weight cell in column C is blank.')
            block.append(record)
        commit()
        if output:
            for index, record in enumerate(output, 1):
                record.index = index
            return output
    return None


def make_project_from_bytes(raw, source_name, run_name=''):
    sheets = read_sheets(raw, source_name)
    candidates, problems = [], []
    try:
        formula_cells = _spreadsheet_formula_metadata(raw)
        formula_problem = ''
    except Exception as exc:
        formula_cells = {}
        formula_problem = 'Formula provenance could not be inspected: ' + str(exc)
    for sheet_name, rows in sheets:
        if not rows:
            continue
        # A finished laboratory report can resemble a labelled export. Its group
        # boundaries and shifted weight cells must be recognized before that fallback.
        for fmt, parser in [('Eager 300 native export', parse_native_headerless),
                            ('Historical completed report', parse_completed_report),
                            ('Labelled CHNS export', parse_native_with_header)]:
            try:
                records = parser(rows)
            except Exception as exc:
                problems.append(f'{sheet_name}/{fmt}: {exc}')
                continue
            if records:
                _attach_spreadsheet_provenance(records, sheet_name, rows, fmt, formula_cells)
                candidates.append((fmt, sheet_name, records, rows))
                break
    if not candidates:
        message = 'Could not recognize CHNS measurements. Choose a native Eager 300 export or a completed laboratory report.'
        if problems:
            message += '\n' + '\n'.join(problems[:4])
        raise ValueError(message)
    candidates.sort(key=lambda value: ('Historical' in value[0], -len(value[2])))
    fmt, sheet, records, used_rows = candidates[0]
    if 'Historical' not in fmt:
        guess_roles(records)
    project = Project(records=records, input_format=fmt + ' / ' + sheet,
                      source_name=source_name, source_sha256=file_hash(raw),
                      derived_from_report='Historical' in fmt,
                      settings=Settings(run_name=run_name or Path(source_name.split('::')[-1]).stem))
    if raw[:8] == bytes.fromhex('D0CF11E0A1B11AE1') and len(raw) % 512:
        project.input_warnings.append('A partial XLS OLE sector was padded in memory for reading; the source file is unchanged.')
    if project.derived_from_report:
        project.input_warnings.append('HISTORICAL REPORT: measurements may already contain manual corrections or derived values. '
                                      'Original instrument calibration, dates and bypass information are not established by this file. '
                                      'Cached formula values retain their formula provenance and are not counted as independent measurements.')
        manual_means = sum(any(key(value) in ('avg', 'avg.', 'average') for value in row if isinstance(value, str))
                           for row in used_rows)
        group_count = len(group_records(project))
        if manual_means < group_count:
            project.input_warnings.append(f'Only {manual_means} of {group_count} historical groups have an existing average row; '
                                          'unfinished groups are not validated manual summaries.')
    formula_count = sum(element in r.formulas for r in records for element in ELEMENTS)
    if formula_count:
        project.input_warnings.append(f'{formula_count} element input cell(s) contain formulas. Cached values and formula text are preserved as derived inputs.')
    if formula_problem:
        project.input_warnings.append(formula_problem + ' Imported values remain available, but require provenance review.')
        for record in records:
            _add_review_flag(record, 'Provenance review: formula inspection was unavailable for this source.')
            for element in ELEMENTS:
                _initial_state(record, element, 'review')
    if len(candidates) > 1:
        project.input_warnings.append('Multiple CHNS-like sheets found; used ' + sheet + '.')
    if not any(record.role == 'Sample' for record in records):
        project.input_warnings.append('No research samples recognized; review roles in Identification.')
    return _initialize_imported_project(project)


def import_file(path, member=None, run_name='', companion=None, native_mode='auto'):
    """Use MTH as the entry point; choose a saved summary or native DAT records."""
    if native_mode not in ('auto', 'saved_dat', 'summary'):
        raise ValueError('Select Automatic, Saved DAT results or Processed summary.')
    path = Path(path)
    if path.is_dir():
        if member is not None or companion is not None:
            raise ValueError('Select a folder without a separate companion/member.')
        path = _find_run_source_folder(path)
    if path.suffix.lower() == '.zip' and member is None:
        raise ValueError('Select one CHNS run (.MTH) or spreadsheet from inside the ZIP archive first.')
    filename = member if member is not None else path.name
    extension = Path(filename).suffix.lower()
    if extension in ('.mth', '.sum'):
        if native_mode == 'auto' and extension == '.mth' and companion is None:
            return project_from_mth_dat(path, member, run_name)
        if native_mode == 'saved_dat':
            if companion is not None:
                raise ValueError('A SUM companion cannot be selected in Saved DAT mode.')
            if extension == '.sum':
                method = _matching_partner(path, '.mth', member=member)
                if method is None:
                    raise MissingCompanionError('Select the .MTH method to read its sequence and matching saved chromatograms.')
                return project_from_mth_dat(path if member is not None else method,
                                            method if member is not None else None, run_name)
            return project_from_mth_dat(path, member, run_name)
        if extension == '.mth':
            mth_raw, mth_source = source_bytes(path, member)
            if companion is not None:
                if member is not None:
                    raise ValueError('Explicit companion paths are supported only for local .MTH files.')
                if Path(companion).suffix.lower() != '.sum':
                    raise ValueError('The companion must be a .SUM summary file.')
                sum_path, sum_member = Path(companion), None
            else:
                partner = _matching_partner(path, '.sum', member=member)
                if partner is None:
                    if native_mode == 'summary':
                        raise MissingCompanionError('Processed summary mode requires a matching .SUM. Select Automatic or Saved DAT results to open the .MTH sequence without a SUM.')
                    return project_from_mth_dat(path, member, run_name)
                sum_path = path if member is not None else Path(partner)
                sum_member = partner if member is not None else None
            sum_raw, sum_source = source_bytes(sum_path, sum_member)
        else:
            if companion is not None:
                raise ValueError('A separate SUM companion is only valid with a selected MTH file.')
            sum_path, sum_member = path, member
            sum_raw, sum_source = source_bytes(path, member)
            partner = _matching_partner(path, '.mth', member=member)
            if partner is not None:
                mth_raw, mth_source = source_bytes(path if member is not None else partner,
                                                 partner if member is not None else None)
            else:
                mth_raw = mth_source = None
        project = project_from_native(sum_raw, sum_source, mth_raw=mth_raw, mth_source=mth_source, run_name=run_name)
        context = None
        if mth_raw is not None:
            try:
                context = _native_method_context(mth_raw, mth_source)
            except ValueError as exc:
                project.input_warnings.append('Detailed MTH inspection is unavailable: ' + str(exc) + '. The selected SUM remains the saved numerical source.')
        return _finish_native_import(project, sum_path, sum_member, method_info=context)
    if companion is not None:
        raise ValueError('A companion .SUM is only valid with a .MTH source.')
    if extension not in ('.xls', '.xlsx', '.csv', '.tsv', '.txt'):
        raise ValueError('Choose a .MTH, .SUM, XLS, XLSX, CSV or run folder.')
    raw, source = source_bytes(path, member)
    project = make_project_from_bytes(raw, source, run_name=run_name)
    project.source_files = [_file_manifest('Spreadsheet export', source, raw)]
    return project


# ---------------------- independent calculation engine ----------------------

def group_records(project:Project):
    groups={};order=[]
    for r in project.records:
        if r.role not in ('Sample','Check'):continue
        name=tidy(r.group or r.name)
        if not name:continue
        identity=(r.role,key(name))
        if identity not in groups:
            groups[identity]=[];order.append(identity)
        groups[identity].append(r)
    return [(k,groups[k]) for k in order]


def compute_results(project: Project, reporting=False) -> list[GroupResult]:
    """Compute accepted diagnostic values, or the numeric values shown in reports.

    Reporting mode includes eligible saved unquantified zeros without altering
    their source state. Both individual rows and aggregate arithmetic use the
    same value provider. The default remains the accepted diagnostic view.
    """
    initialize_project_review(project)
    st = project.settings
    register_certificates(project_certificates(project))
    if st.reference_table not in REFERENCES and st.reference_table not in project_certificates(project):
        raise ValueError('Unrecognized reference table.')
    if isinstance(st.expected_replicates, bool) or not isinstance(st.expected_replicates, int) or not 1 <= st.expected_replicates <= 20:
        raise ValueError('Expected replicates must be an integer between 1 and 20.')
    if st.high_rsd_enabled and (not math.isfinite(st.high_rsd_pct) or st.high_rsd_pct <= 0):
        raise ValueError('High-RSD threshold must be a positive percentage.')
    reference, outputs = reference_values(project, st.reference_table), []
    value_for_statistics = report_value if reporting else _accepted_unless_failed
    count_label = 'reported' if reporting else 'accepted' 
    for (role, group_key), rows in group_records(project):
        label = tidy(rows[0].group or rows[0].name)
        flags, notes = [], []
        means, sds, rsds, counts, difference = {}, {}, {}, {}, {}
        if len(rows) != st.expected_replicates and role == 'Sample':
            flags.append('REPLICATE_COUNT')
            notes.append(f'{len(rows)} separately weighed portions; expected {st.expected_replicates}. '
                         f'The {count_label} n is recorded separately for each element in the technical information.')
        if len(set(key(r.name) for r in rows)) < len(rows):
            flags.append('DUPLICATE_LABEL')
            notes.append('Some measurement names are identical; confirm they refer to separate portions.')
        if any(r.weight_mg is None or r.weight_mg <= 0 for r in rows):
            flags.append('MISSING_WEIGHT')
            notes.append('A portion has missing or nonpositive mass. Reported % w/w is never rescaled by mass.')
        for e in ELEMENTS:
            clean = [v for r in rows if (v := value_for_statistics(r, e)) is not None]
            states = Counter(measurement_state(r, e) for r in rows)
            counts[e] = len(clean)
            means[e] = statistics.mean(clean) if clean else None
            sds[e] = statistics.stdev(clean) if len(clean) >= 2 else None
            rsds[e] = 100 * sds[e] / abs(means[e]) if sds[e] is not None and abs(means[e]) > 1e-12 else None
            if not clean:
                flags.append('NO_' + e)
                notes.append(f'{NAMES[e]}: no {count_label} numerical value; mean and SD are not reported.')
            if len(clean) != len(rows):
                flags.append('INCOMPLETE_' + e)
                if reporting:
                    withheld_states = Counter(measurement_state(r, e) for r in rows
                                              if value_for_statistics(r, e) is None)
                    withheld = ', '.join(f'{STATE_LABELS[state]}: {n}'
                                         for state, n in withheld_states.items())
                else:
                    withheld = ', '.join(f'{STATE_LABELS[state]}: {n}' for state, n in states.items()
                                         if state not in ('measured', 'revised', 'reported_zero'))
                notes.append(f'{NAMES[e]}: n={len(clean)} {count_label} out of {len(rows)} portions. {withheld}.')
            if states['review']:
                flags.append('REVIEW_' + e)
            if states['derived']:
                flags.append('DERIVED_' + e)
                notes.append(f'{NAMES[e]} has a derived/formula input, excluded from independent replicate statistics pending review.')
            if states['revised']:
                flags.append('REVISED_' + e)
            if states['reported_zero']:
                flags.append('REPORTED_ZERO_' + e)
                notes.append(f'{NAMES[e]} includes {states["reported_zero"]} saved zero(s) under an explicit laboratory reporting convention; this does not establish quantification or a detection limit.')
            saved_report_zeros = [r for r in rows if _saved_zero_report_eligible(r, e)] if reporting else []
            if saved_report_zeros:
                flags.append('SAVED_ZERO_REPORTED_' + e)
                notes.append(f'{NAMES[e]}: {len(saved_report_zeros)} saved unquantified numerical zero(s) '
                             f'reported as 0 under {REPORT_CONVENTION_ID}. These zeros enter reported n, '
                             'mean and SD; source values and unquantified states are unchanged.')
            corrected = [r for r in rows if (r.corrections.get(e) or {}).get('active')]
            if corrected:
                flags.append('REFERENCE_CORRECTION_' + e)
                notes.append(f'{NAMES[e]}: an explicitly reviewed additive reference correction is recorded. See reference, check values, offsets and zero policy in the correction audit.')
                stale = [r for r in corrected if (r.corrections[e].get('stale_reason')
                         or r.corrections[e].get('outcome') == 'out_of_range') and source_accepted_value(r, e) is not None]
                if stale:
                    flags.append('CORRECTION_REVIEW_' + e)
                    notes.append(f'{NAMES[e]}: {len(stale)} corrected result(s) are withheld pending a fresh preview or validity review.')
            original = [effective_value(r, e) for r in rows]
            if any(isinstance(v, (int, float)) and (not math.isfinite(v) or v < 0 or v > 100) for v in original):
                flags.append('OUT_OF_RANGE_' + e)
                notes.append(f'{NAMES[e]} contains a selected input outside 0–100 %; it cannot enter accepted statistics.')
            if any(v == 0 for v in clean):
                flags.append('ZERO_' + e)
                notes.append(f'{NAMES[e]} includes a {count_label} numeric zero; zero alone does not establish a detection limit.')
            if st.high_rsd_enabled and rsds[e] is not None and rsds[e] > st.high_rsd_pct:
                flags.append('HIGH_RSD_' + e)
                notes.append(f'{NAMES[e]} RSD {rsds[e]:.2f}% exceeds the chosen {st.high_rsd_pct:g}% information threshold.')
        if any(sum(value_for_statistics(r, e) or 0 for e in ELEMENTS) > 100.00001 for r in rows):
            flags.append('TOTAL_ABOVE_100')
            notes.append(f'At least one portion has a {count_label} CHNS total above 100 %. Review analytical processing; totals are not automatically normalized.')
        if any('ALL_ZERO_PORTION' in r.review_flags for r in rows):
            flags.append('ALL_ZERO_ROW')
            notes.append('An originally all-zero portion is retained in the audit. It is withheld unless an explicit review or replacement resolves it.')
        for r in rows:
            for flag in r.review_flags:
                if flag not in ('ALL_ZERO_PORTION',):
                    flags.append(flag)
                    notes.append(f'{r.name}: {flag}. See measurement/source review details.')
        if role == 'Check':
            material = check_material(label) or check_material(rows[0].name)
            if material and material in reference:
                difference = {e: means[e] - reference[material][e] if means[e] is not None and reference[material].get(e) is not None
                              else None for e in ELEMENTS}
                notes.append(('Reported check mean' if reporting else 'Check') +
                             ' minus selected reference in percentage points; no automatic acceptance tolerance is assumed.')
                if reporting:
                    notes.append('The Check references diagnostic sheet and correction eligibility use accepted source values; '
                                 'a reporting-convention zero is not a quantified check measurement.')
            else:
                notes.append('No matching reference comparison selected; no certified values or acceptance limits assumed.')
        outputs.append(GroupResult(label, role, [r.index for r in rows], means, sds, rsds, counts,
                                   list(dict.fromkeys(flags)), list(dict.fromkeys(notes)), difference))
    return outputs


def analysis_summary(project):
    results = compute_results(project)
    return {'records': len(project.records), 'role_counts': dict(Counter(r.role for r in project.records)),
            'groups': sum(r.role == 'Sample' for r in results), 'checks': sum(r.role == 'Check' for r in results),
            'flagged_groups': sum(bool(r.flags) for r in results),
            'sample_replicates': sum(len(r.indices) for r in results if r.role == 'Sample'),
            'element_states': dict(Counter(measurement_state(r, e) for r in project.records
                                          if r.role == 'Sample' for e in ELEMENTS)),
            'report_status': report_readiness(project)['status']}


def apply_edits(project, changes):
    draft = copy.deepcopy(project.records)
    by_index = {r.index: r for r in draft}
    if len(by_index) != len(draft):
        raise ValueError('Duplicate measurement indices in project.')
    seen = set()
    for edit in changes:
        idx = int(edit['index'])
        if idx not in by_index or idx in seen:
            raise ValueError(f'Invalid/duplicate measurement number {idx}.')
        seen.add(idx)
        role, group = tidy(edit['role']), tidy(edit.get('group', ''))
        if role not in ROLES:
            raise ValueError(f'Invalid role {role!r}.')
        if role in ('Sample', 'Check') and not group:
            raise ValueError(f'Measurement {idx}: a sample or check needs a group name.')
        r = by_index[idx]
        old_role = r.role
        r.role, r.group, r.identity_reviewed = role, group, True
        if old_role not in ('Sample', 'Check') and role in ('Sample', 'Check'):
            for e in ELEMENTS:
                if not r.review_notes.get(e) and not r.revisions.get(e):
                    r.states.pop(e, None)
            initialize_measurement_review(r)
    if not any(r.role == 'Sample' for r in draft):
        raise ValueError('At least one research sample is required.')
    changed = [asdict(r) for r in project.records] != [asdict(r) for r in draft]
    project.records = draft
    if changed:
        _invalidate_source_review(project)
        project.decisions.append({'time_utc': utc_now(), 'action': 'identification_confirmed', 'changes': copy.deepcopy(changes)})


def set_settings(project, **changes):
    new = copy.deepcopy(project.settings)
    allowed = {f.name for f in fields(Settings)}
    for k, v in changes.items():
        if k not in allowed:
            raise ValueError(f'Unknown setting: {k}')
        setattr(new, k, v)
    draft = copy.deepcopy(project)
    draft.settings = new
    _store_project_certificate(draft, new.reference_table)
    compute_results(draft)
    changed = asdict(project.settings) != asdict(new)
    project.settings = new
    stored = (draft.processing or {}).get('certificates') if isinstance(draft.processing, dict) else None
    if stored:
        if not isinstance(getattr(project, 'processing', None), dict):
            project.processing = {}
        project.processing['certificates'] = copy.deepcopy(stored)
    if changed:
        _invalidate_source_review(project)
        project.decisions.append({'time_utc': utc_now(), 'action': 'settings_confirmed', 'settings': asdict(new)})


def save_project(project, path):
    """Save a complete model snapshot, including incomplete analytical review.

    This API stays compatible with earlier releases and report export. Saving
    does not confirm identities, apply pending edits or create source approval.
    """
    payload = _project_snapshot_payload(project)
    _atomic_project_snapshot_write(payload, path)


def load_project(path):
    """Reopen the calculation model; load_workspace also returns unsaved editor values."""
    return _project_from_snapshot_payload(_read_project_snapshot(path))

# ----------------------- Excel / Word report export --------------------------

def _excel_imports():
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font,PatternFill,Border,Side,Alignment
        return Workbook,Font,PatternFill,Border,Side,Alignment
    except ImportError as exc:
        raise RuntimeError('Excel export requires openpyxl: pip install openpyxl') from exc


def _sheet_header(ws,headers,row=1):
    _,Font,PatternFill,_,_,Alignment=_excel_imports()
    for i,heading in enumerate(headers,1):
        cell=ws.cell(row,i,safe_cell(heading))
        cell.fill=PatternFill('solid',fgColor='20334B')
        cell.font=Font(name='Arial',size=10,bold=True,color='FFFFFF')
        cell.alignment=Alignment(wrap_text=True,vertical='center')
    ws.row_dimensions[row].height=32


def _notes_sheet(wb, project: Project, groups: list[GroupResult], include_qc=True):
    groups = compute_results(project, reporting=True)
    accepted_groups = compute_results(project)
    ws = wb.create_sheet('Run information')
    _sheet_header(ws, ['Field', 'Value'])
    s = project.settings
    readiness = report_readiness(project)
    correction = _correction_export_context(project)
    rows = [('Application', f'{APP_NAME} {APP_VERSION}'), ('Report status', readiness['status']),
            ('Run', s.run_name), ('Requester', s.requester), ('Source', project.source_name),
            ('Format', project.input_format), ('Source SHA-256', project.source_sha256),
            ('Generated UTC', utc_now()), ('Expected separately combusted portions', s.expected_replicates),
            ('Average', 'Arithmetic mean of reported numerical values, separately for each element. Eligible saved unquantified zeros are reported as 0 and enter the mean and SD. Approved reference corrections and explicit reported-zero decisions remain identified in the review trail.'),
            ('Standard deviation', 'Sample standard deviation with n−1 (Excel STDEV.S); blank if n<2.'),
            ('Reported n', 'Number of numeric values used for that element in the report statistics, including eligible saved unquantified zeros. Counts are retained in this sheet and technical outputs; the final result table shows avg. and stdev. only.'),
            ('Accepted n', 'Diagnostic count of accepted numerical results. Source unquantified values do not enter accepted n, even when the saved-zero report convention includes them in reported n.'),
            ('Measurement review counts', 'The existing Included in n column means included in accepted n. The appended Included in reported n column identifies the values used for report arithmetic.'),
            ('Report conventions', REPORT_CONVENTION_ID + '; ' + NATIVE_ZERO_CONVENTION_ID),
            ('Mass handling', 'Recorded mg retained. Saved instrument percentages are not multiplied by mass again. New detector processing converts area to elemental mass, then divides by recorded portion mass.'),
            ('Original data', 'Never overwritten. Independent revised values require identified source, mapping, reviewer and reason. Optional calculated corrections are stored separately.'),
            ('Withheld result labels', 'Held: needs review; Missing: no numeric source value; Derived: formula/estimate; Excluded: deliberate review decision; < limit: censored. NQ / Not quantified remains a source-review status; eligible saved zeros are reported as 0. An unassigned element requires a peak assignment or an explicitly reviewed reporting zero.'),
            ('Zero handling', 'An ordinary quantified zero remains numeric. Under the fixed report convention an eligible saved unquantified numerical zero contributes 0 to reported n, mean and SD, while its original state and accepted n are unchanged. Formula, conflicted, all-zero failed, excluded, missing-file and censored inputs are not converted to zero. An absent element-assigned peak remains unresolved until reviewed; a documented visual reporting-zero decision is retained separately. Explicit reviewed reported-zero decisions remain separately labelled. A reporting zero does not establish quantification or a detection limit.'),
            ('Automatic corrections', 'Native processing proposes baseline, peak bounds and calibration from verified traces. Applied decisions are recorded. No replacement is chosen to improve triplicate or manual-report agreement. Reference offsets remain a separate explicit operation.'),
            ('Reference correction', correction['status']),
            ('Correction formula', 'Configured offset = selected reference − mean of explicitly selected eligible measured checks. Corrected result = source base + applied offset; applied offset is 0 for a preserved zero and absent for a held source. See Reference correction for provenance and outcomes.'),
            ('Correction zero policy', correction['zero_policy']),
            ('Correction validity', 'No automatic clipping or normalization. Invalid or stale corrected values are withheld; originals are retained.'),
            ('Native processing scope', 'A MTH entry point independently reads its DAT detector records. Saved source results remain available. Native processing can propose new intervals and baselines, fit reviewed calibration standards, and recalculate concentrations. Every applied change is retained with its source, settings and reviewer. Missing or conflicting acquisitions stay unresolved.'),
            ('Reference set', s.reference_table),
            ('Reference rule', 'Diagnostic QC uses uncorrected accepted check values. Reported check statistics, if included, use the same saved-zero convention as the report. No laboratory pass/fail tolerance is assumed. The optional correction reference is recorded separately.'),
            ('High RSD information threshold', f'{s.high_rsd_pct:g}%' if s.high_rsd_enabled else 'Not enabled'),
            ('Source reviewer', project.source_review.get('reviewer', '')),
            ('Source verification note', project.source_review.get('note', '')),
            ('Source review time UTC', project.source_review.get('time_utc', '')),
            ('Analyst notes', s.analyst_notes)]
    for message in readiness['blockers']:
        rows.append(('Review needed', message))
    for source in project.source_files:
        rows.append(('Source file', f"{source.get('role', '')}: {source.get('name', '')} | SHA-256: {source.get('sha256', '')}"))
    for note in project.input_warnings:
        rows.append(('Import note', note))
    accepted_by_indices = {(g.role, tuple(g.indices)): g for g in accepted_groups}
    for g in groups:
        rows.append(('Reported n — ' + g.name, ', '.join(f'{e}: {g.counts[e]}' for e in ELEMENTS)))
        accepted = accepted_by_indices.get((g.role, tuple(g.indices)))
        if accepted is not None:
            rows.append(('Accepted n — ' + g.name, ', '.join(f'{e}: {accepted.counts[e]}' for e in ELEMENTS)))
        if include_qc and g.flags:
            rows.append(('Group review — ' + g.name, '; '.join(g.flags)))
    for label, value in rows:
        ws.append([safe_cell(label), safe_cell(str(value) if value is not None else '')])
    ws.column_dimensions['A'].width = 38
    ws.column_dimensions['B'].width = 115
    ws.freeze_panes = 'A2'
    _, Font, _, _, _, Alignment = _excel_imports()
    for cells in ws.iter_rows(min_row=2):
        for cell in cells:
            cell.font = Font(name='Arial', size=10)
            cell.alignment = Alignment(vertical='top', wrap_text=cell.column == 2)
    _reference_correction_sheet(wb, project)
    _native_processing_sheet(wb, project)
    return ws


def _report_rows(project,groups,include_checks=False):
    record_by_id={r.index:r for r in project.records}
    for group in groups:
        if group.role!='Sample' and not (include_checks and group.role=='Check'):continue
        yield group,[record_by_id[i] for i in group.indices]


def write_archive_style_report(project:Project,groups:list[GroupResult],path):
    """Write the clean laboratory report in the archived CHNS Excel layout.

    Styled after the laboratory's earlier result workbooks (Results/*.XLS). The first worksheet
    retains the archived typography and grid, without an n row or red banner.
    This reproduces the lab's worksheet cosmetics, not the binary XLS format.
    Source verification/QC information remains in the separate 'Run information'
    worksheet and in the independent review/calculation workbooks.

    Source layout: A=left margin, B=sample, C=mass, D=statistic labels,
    E-H=N,C,H,S; two header rows, then replicates, avg., stdev., blank row.
    Source appearance: Arial 10, black thin borders, no shading, 12.75 pt rows,
    right-aligned sample names, reference column widths (Excel characters).
    """
    # Recompute at the public writer boundary so legacy callers cannot pair
    # newly displayed zeros with an older accepted-only mean or SD.
    groups = compute_results(project, reporting=True)
    Workbook,Font,_PatternFill,Border,Side,Alignment=_excel_imports()
    wb=Workbook()
    ws=wb.active
    ws.title='Sheet1'  # original Eager laboratory reports use Sheet1
    ws.sheet_view.showGridLines=True
    ws.sheet_format.defaultRowHeight=12.75
    # Widths decoded from the 21 September 2026 archival BIFF8 COLINFO records.
    for column,width in {'A':6.00,'B':22.00,'C':11.86,'D':6.71,
                         'E':11.86,'F':11.86,'G':11.86,'H':11.86}.items():
        ws.column_dimensions[column].width=width
    ink='000000'
    thin=Side(style='thin',color=ink)
    bordered=Border(left=thin,right=thin,top=thin,bottom=thin)
    header_top=Border(left=thin,right=thin,top=thin)
    header_bottom=Border(left=thin,right=thin,bottom=thin)
    side_only=Border(left=thin,right=thin)
    side_top=Border(left=thin,right=thin,top=thin)
    side_bottom=Border(left=thin,right=thin,bottom=thin)
    side_top_bottom=Border(left=thin,right=thin,top=thin,bottom=thin)
    font_regular=Font(name='Arial',size=10,bold=False,color=ink)
    font_bold=Font(name='Arial',size=10,bold=True,color=ink)
    centered=Alignment(horizontal='center',vertical='center')
    aligned_right=Alignment(horizontal='right',vertical='center')
    # Exact header cell coordinates used by the lab (row 1 is blank).
    ws['C2']='Weight'
    ws['B3']='Sample'
    ws['C3']='(mg)'
    for j,e in enumerate(ELEMENTS,5):
        ws.cell(2,j,NAMES[e])
        ws.cell(3,j,'(% w/w)')
    for r in (2,3):
        for c in (2,3,5,6,7,8):
            cell=ws.cell(r,c)
            cell.font=font_bold
            cell.alignment=centered
            if c in (2,3):
                cell.border=header_top if r==2 else header_bottom
            else:
                cell.border=bordered
    # The old format leaves a narrow, partly outlined D-column header gap.
    ws['D2'].border=Border(left=thin,top=thin)
    ws['D3'].border=Border(right=thin,top=thin)
    row=4
    fmt_raw='0.00000000'
    fmt_mean='0.0000'
    fmt_sd='0.00000'
    fmt_zero='0.0'  # the archive shows zero as 0.0, not 0.00000000
    for group,records in _report_rows(project,groups,include_checks=project.settings.include_check_in_report):
        n=len(records)
        for i,rec in enumerate(records):
            sample_cell=ws.cell(row,2,safe_cell(rec.name))
            sample_cell.font=font_bold
            sample_cell.alignment=aligned_right
            sample_cell.border=bordered
            weight=ws.cell(row,3,rec.weight_mg)
            weight.font=font_regular
            weight.alignment=aligned_right
            weight.border=bordered
            if rec.weight_mg is not None:weight.number_format='0.000'
            # Column D has vertical boundaries and only a top at the first
            # replicate and a bottom at the last (no internal horizontal lines).
            d=ws.cell(row,4)
            d.font=font_regular
            d.alignment=aligned_right
            if n==1:d.border=side_top_bottom
            elif i==0:d.border=side_top
            elif i==n-1:d.border=side_bottom
            else:d.border=side_only
            for j,e in enumerate(ELEMENTS,5):
                value=report_value(rec,e)
                if value is None:value=report_value_text(rec,e)
                cell=ws.cell(row,j,value)
                cell.font=font_regular
                cell.alignment=aligned_right
                cell.border=bordered
                if isinstance(value,(int,float)):
                    cell.number_format=fmt_zero if value==0 else fmt_raw
            ws.row_dimensions[row].height=12.75
            row+=1
        for label,stats,number_format in (('avg.',group.means,fmt_mean),
                                          ('stdev.',group.sds,fmt_sd)):
            tag=ws.cell(row,4,label)
            tag.font=font_bold
            tag.alignment=aligned_right
            for j,e in enumerate(ELEMENTS,5):
                value=stats[e]
                cell=ws.cell(row,j,value)
                cell.font=font_bold
                cell.alignment=aligned_right
                cell.border=bordered
                if value is not None:
                    cell.number_format=fmt_zero if value==0 else number_format
            ws.row_dimensions[row].height=12.75
            row+=1
        ws.row_dimensions[row].height=12.75  # blank row between sample groups
        row+=1
    ws.row_dimensions[1].height=12.75
    ws.row_dimensions[2].height=12.75
    ws.row_dimensions[3].height=12.75
    # Preserve review status in the filename, Run information and a neutral footer.
    readiness=report_readiness(project)
    ws.oddFooter.center.text='CHNSetti '+APP_VERSION
    ws.oddFooter.center.size=8
    _notes_sheet(wb,project,groups,include_qc=False)
    wb.save(path)


def write_results_workbook(project:Project,groups:list[GroupResult],path,*,review=False):
    if not review:
        return write_archive_style_report(project,groups,path)

    groups = compute_results(project, reporting=True)
    Workbook,Font,PatternFill,Border,Side,Alignment=_excel_imports()
    wb=Workbook();ws=wb.active;ws.title='CHNS results'
    ws.sheet_view.showGridLines=False
    readiness=report_readiness(project)
    ws.merge_cells('B1:I1')
    ws['B1']=readiness['status']+' — reported statistics include eligible saved zeros; accepted source states remain in detailed review'
    ws['B1'].font=Font(name='Arial',bold=True,size=10,color='14532D' if readiness['ready'] else '9C1919')
    ws['B1'].alignment=Alignment(wrap_text=True,vertical='center')
    ws.row_dimensions[1].height=33
    ws['C2']='Weight'
    for j,e in enumerate(ELEMENTS,5):ws.cell(2,j,NAMES[e])
    ws['B3']='Sample';ws['C3']='(mg)'
    for j in range(5,9):ws.cell(3,j,'(% w/w)')
    if review:ws['I3']='Review remarks'
    border_side=Side(style='thin',color='98A6B3')
    cell_border=Border(left=border_side,right=border_side,top=border_side,bottom=border_side)
    fmt={'raw':'0.00000000','mean':'0.0000','sd':'0.00000','n':'0'}
    for cells in ws.iter_rows(min_row=2,max_row=3,min_col=2,max_col=9 if review else 8):
        for c in cells:
            c.font=Font(name='Arial',size=10,bold=True,color='172B4D')
            c.alignment=Alignment(horizontal='center',vertical='center',wrap_text=True)
            if c.column!=4:c.border=cell_border
    ws.row_dimensions[3].height=29
    row=4
    for g,records in _report_rows(project,groups,include_checks=project.settings.include_check_in_report):
        for rec in records:
            ws.cell(row,2,safe_cell(rec.name));wc=ws.cell(row,3,rec.weight_mg)
            if rec.weight_mg is not None:wc.number_format='0.000'
            for j,e in enumerate(ELEMENTS,5):
                value=report_value(rec,e)
                c=ws.cell(row,j,value if value is not None else safe_cell(report_value_text(rec,e)));c.number_format=fmt['raw']
            for col in (2,3,5,6,7,8):
                cell=ws.cell(row,col);cell.border=cell_border
                cell.font=Font(name='Arial',size=10,color='1F2937')
                cell.alignment=Alignment(horizontal='right' if col!=2 else 'left')
            if review:
                remarks = [e+': '+measurement_status_label(rec,e) for e in ELEMENTS]
                remarks.extend(e+': '+report_value_convention(rec,e) for e in ELEMENTS
                               if report_value_convention(rec,e))
                ws.cell(row,9,safe_cell('; '.join(remarks + rec.notes)))
                ws.cell(row,9).font=Font(name='Arial',size=9,color='64748B')
            row+=1
        for title,figures,typ in (('avg.',g.means,'mean'),('stdev.',g.sds,'sd'),('n reported',g.counts,'n')):
            ws.cell(row,4,title)
            for j,e in enumerate(ELEMENTS,5):
                c=ws.cell(row,j,figures[e]);c.number_format=fmt[typ]
            if review and title=='avg.':ws.cell(row,9,'; '.join(g.flags) or 'No flags')
            if review and title=='stdev.':ws.cell(row,9,'; '.join(g.messages))
            for j in (4,5,6,7,8):
                c=ws.cell(row,j)
                c.font=Font(name='Arial',size=10,bold=True,color='1F2937')
                if j>4:c.border=cell_border
                c.alignment=Alignment(horizontal='right')
                if review:
                    serious=any(x.startswith(('OUT_OF_RANGE','HIGH_RSD','INCOMPLETE','REPLICATE_COUNT','MISSING_WEIGHT'))
                                or x=='TOTAL_ABOVE_100' for x in g.flags)
                    if serious:c.fill=PatternFill('solid',fgColor='FEE2E2')
                    elif g.flags:c.fill=PatternFill('solid',fgColor='FFF7ED')
            row+=1
        row+=1    # the laboratory's blank separator row
    ws.column_dimensions['A'].width=3;ws.column_dimensions['B'].width=32
    ws.column_dimensions['C'].width=11;ws.column_dimensions['D'].width=12
    for x in 'EFGH':ws.column_dimensions[x].width=16
    if review:ws.column_dimensions['I'].width=62
    ws.freeze_panes='E4';ws.print_options.horizontalCentered=True
    ws.page_setup.orientation='landscape';ws.page_setup.paperSize=ws.PAPERSIZE_A4
    ws.page_setup.fitToWidth=1;ws.page_setup.fitToHeight=0
    ws.sheet_properties.pageSetUpPr.fitToPage=True
    ws.print_title_rows='2:3'
    if review:
        _notes_sheet(wb,project,groups)
        qc=wb.create_sheet('Review flags')
        _sheet_header(qc,['Group','Role','Flags','Details'])
        for g in groups:
            if g.flags:
                qc.append([safe_cell(g.name),g.role,'; '.join(g.flags),'; '.join(g.messages)])
        qc.column_dimensions['A'].width=32;qc.column_dimensions['B'].width=15
        qc.column_dimensions['C'].width=45;qc.column_dimensions['D'].width=100
    else:
        _notes_sheet(wb,project,groups,include_qc=False)
    wb.save(path)


def write_detailed_workbook(project:Project,groups:list[GroupResult],path):
    groups = compute_results(project, reporting=True)
    accepted_groups = compute_results(project)
    Workbook,Font,PatternFill,Border,Side,Alignment=_excel_imports()
    wb=Workbook();raw=wb.active;raw.title='Original measurements'
    _sheet_header(raw,['#','Original sample name','Saved file ID','Date','Time','Instrument type',
                       'Analyst role','Group name','Weight (mg)','Nitrogen (% w/w)','Carbon (% w/w)',
                       'Hydrogen (% w/w)','Sulfur (% w/w)','Source record/Excel row','Input notes'])
    for r in project.records:
        raw.append([r.index,safe_cell(r.name),safe_cell(r.file_id),r.date,r.time,r.instrument_type,
                    r.role,safe_cell(r.group),r.weight_mg]+[r.values.get(e) for e in ELEMENTS]+
                   [r.source_row,'; '.join(r.notes)])
        for col in range(9,14):
            raw.cell(raw.max_row,col).number_format='0.000' if col==9 else '0.00000000'
    raw.freeze_panes='C2';raw.auto_filter.ref=raw.dimensions
    stats=wb.create_sheet('Group statistics')
    _sheet_header(stats,['Group','Role','Element','n reported','Mean (% w/w)','Sample SD (% w/w)',
                         'RSD (%)','Flags','Reference (% w/w)','Check - reference (pp)','Formula / explanation'])
    ref=reference_values(project)
    for g in groups:
        material=check_material(g.name)
        for e in ELEMENTS:
            stored=ref.get(material,{}).get(e) if g.role=='Check' else None
            stats.append([safe_cell(g.name),g.role,e,g.counts[e],g.means[e],g.sds[e],g.rsds[e],
                          '; '.join(g.flags),stored,g.standard_differences.get(e),
                          'Reported numeric values, including eligible saved unquantified zeros reported as 0. Source accepted values and reporting conventions are retained separately. mean = SUM(values)/n; sample SD = sqrt(SUM((xi-mean)^2)/(n-1)); '
                          'RSD = 100*SD/abs(mean)'])
            stats.cell(stats.max_row,5).number_format='0.00000000'
            stats.cell(stats.max_row,6).number_format='0.00000000'
            stats.cell(stats.max_row,7).number_format='0.00'
    stats.freeze_panes='D2';stats.auto_filter.ref=stats.dimensions
    qc=wb.create_sheet('Quality review')
    _sheet_header(qc,['Group','Role','Measurements','Flags','Explanation','Analyst decision'])
    for g in groups:
        qc.append([safe_cell(g.name),g.role,len(g.indices),'; '.join(g.flags) or 'none',
                   '; '.join(g.messages),''])
    qc.freeze_panes='A2';qc.auto_filter.ref=qc.dimensions
    checks=wb.create_sheet('Check references')
    _sheet_header(checks,['Reference material','Reference set','Element','Certified % w/w',
                          'Measured group','Accepted source mean % w/w','Difference (percentage points)','Automatic accept/reject'])
    for g in accepted_groups:
        if g.role!='Check':continue
        mat=check_material(g.name)
        for e in ELEMENTS:
            if mat in ref:
                checks.append([mat,project.settings.reference_table,e,ref[mat].get(e),g.name,
                               g.means[e],g.standard_differences.get(e),'None: no approved tolerance'])
            else:
                checks.append([mat or 'Unresolved',project.settings.reference_table,e,None,
                               g.name,g.means[e],None,'No reference assigned'])
    _notes_sheet(wb,project,groups)
    _measurement_review_sheet(wb,project)
    audit=wb.create_sheet('Analyst decisions')
    _sheet_header(audit,['UTC time','Action','Details'])
    for event in project.decisions:
        audit.append([event.get('time_utc',''),event.get('action',''),json.dumps(event,ensure_ascii=False,default=str)])
    for sheet in wb.worksheets:
        if sheet==raw:
            width={1:7,2:32,3:34,4:16,5:12,6:16,7:16,8:32,9:15,10:17,11:17,
                   12:17,13:17,14:20,15:70}
        elif sheet==stats:
            width={1:30,2:14,3:12,4:16,5:20,6:22,7:14,8:43,9:20,10:27,11:60}
        elif sheet==qc:
            width={1:32,2:14,3:18,4:50,5:105,6:28}
        elif sheet==checks:
            width={1:25,2:32,3:12,4:22,5:25,6:26,7:29,8:40}
        else:
            continue
        for i,w in width.items():sheet.column_dimensions[__import__('openpyxl').utils.get_column_letter(i)].width=w
        for r in sheet.iter_rows(min_row=2):
            for cell in r:
                if cell.data_type=='s' and isinstance(cell.value,str) and cell.value.startswith(('=', '+', '-', '@')):
                    cell.data_type='s'
    wb.save(path)




# ---------------------------------------------------------------------------------------------------------------
# Figures for the Word report (CHNSetti 1.0.0): the calibration curves and every chromatogram, drawn with Qt
# (PySide6 is required anyway) into PNG images. Works in the window and in a headless export.
# ---------------------------------------------------------------------------------------------------------------
FIGURE_COLORS = {'N': '#2563A6', 'C': '#23775E', 'H': '#B76520', 'S': '#7D4CA0'}
_FIGURE_APP = None


def _figure_qt():
    """Qt painting classes, with an application object (offscreen when there is no display)."""
    global _FIGURE_APP
    from PySide6.QtWidgets import QApplication
    from PySide6 import QtGui, QtCore
    app = QApplication.instance()
    if app is None:
        if sys.platform.startswith('linux') and not os.environ.get('QT_QPA_PLATFORM') \
                and not os.environ.get('DISPLAY') and not os.environ.get('WAYLAND_DISPLAY'):
            os.environ['QT_QPA_PLATFORM'] = 'offscreen'
        _FIGURE_APP = app = QApplication([sys.argv[0] if sys.argv else 'CHNSetti'])
    return QtGui, QtCore


def _figure_png(image, QtCore):
    buffer = QtCore.QBuffer(); buffer.open(QtCore.QIODevice.WriteOnly)
    image.save(buffer, 'PNG'); data = bytes(buffer.data()); buffer.close()
    return data


def _figure_number(value, digits=4):
    if value is None or not isinstance(value, (int, float)) or not math.isfinite(value):
        return '—'
    if abs(value) >= 1000:
        return f'{value:,.0f}'.replace(',', ' ')
    return f'{value:.{digits}g}'


def _figure_basis(project):
    """The integration and calibration behind the reported values, for the figures."""
    processing = project.processing or {}
    applied = processing.get('active_preview')
    used = any(_selected_processing(r, e) for r in project.records for e in ELEMENTS)
    if applied and used:
        return applied, ('CHNSetti integration and calibration applied to the report'
                         f" ({(applied.get('settings') or {}).get('boundary_method', 'advanced')} start and end points"
                         ' and the analyst\'s edits).')
    return processing_saved_preview(project), (
        'Integration saved by the instrument software (Eager 300), as reported. The calibration curves are drawn from '
        'the standards\' saved areas with CHNSetti\'s calibration model; the reported values themselves come from the '
        'instrument\'s calibration.')


def _figure_axes_ticks(lo, hi, count=5):
    span = hi - lo
    if span <= 0:
        return [lo]
    raw = span / count; power = 10 ** math.floor(math.log10(raw))
    step = min((m * power for m in (1, 2, 2.5, 5, 10)), key=lambda s: abs(s - raw))
    first = math.ceil(lo / step) * step
    return [first + i * step for i in range(int((hi - first) / step) + 1)]


def figure_area_outline(item, start, end, value_at, bl, br):
    """The shaded area in data units: the signal from start to end, closed along the baseline that was used
    (the straight line, or the fitted curve of asls/arpls). Returns (outline, baseline points)."""
    xs = [float(start)] + [float(i) for i in range(int(math.floor(start)) + 1, int(math.ceil(end)))] + [float(end)]
    by = [float(v) for v in (item.get('baseline') or []) if isinstance(v, (int, float))]
    bx = item.get('baseline_x') or [float(item.get('baseline_start', start)) + i for i in range(len(by))]
    if len(by) < 2 or len(bx) != len(by):
        bx, by = [float(start), float(end)], [float(bl), float(br)]
    baseline = list(zip([float(x) for x in bx], by))
    return [(x, value_at(x)) for x in xs] + list(reversed(baseline)), baseline


def figure_entries(record, preview, saved_preview=None):
    """The integration drawn for each element of a measurement: the one that produced its reported value. A value
    restored to the instrument's result after Apply is drawn with the instrument's integration."""
    entry = dict((((preview or {}).get('records') or {}).get(str(record.index)) or {}).get('elements') or {})
    if saved_preview is not None and record.role in ('Sample', 'Check'):
        saved = ((((saved_preview.get('records') or {}).get(str(record.index)) or {}).get('elements')) or {})
        for element in ELEMENTS:
            if not _selected_processing(record, element) and element in saved:
                entry[element] = saved[element]
    return entry


def figure_chromatogram(record, preview, QtGui, QtCore, saved_preview=None):
    """One measurement: four panels (N, C, H, S), each zoomed to the element's peak with its integration."""
    trace = _processing_trace(record) or {}
    signal = [float(v) for v in trace.get('signal') or []]
    n = len(signal)
    if n < 3:
        return None
    entry = figure_entries(record, preview, saved_preview)
    windows = (preview or {}).get('windows') or {}
    W, H, PAD = 1800, 420, 6
    image = QtGui.QImage(W, H, QtGui.QImage.Format_RGB32); image.fill(QtGui.QColor('white'))
    p = QtGui.QPainter(image); p.setRenderHint(QtGui.QPainter.Antialiasing)
    title_font = QtGui.QFont('Arial'); title_font.setPixelSize(19); title_font.setBold(True)
    small = QtGui.QFont('Arial'); small.setPixelSize(15)

    def value_at(x):
        x = min(max(float(x), 0.0), n - 1.0); i = int(math.floor(x)); f = x - i
        return signal[i] if i >= n - 1 or f == 0 else signal[i] * (1 - f) + signal[i + 1] * f

    width = (W - PAD * 5) / 4
    for k, element in enumerate(ELEMENTS):
        item = entry.get(element) or {}
        colour = QtGui.QColor(FIGURE_COLORS[element])
        box = QtCore.QRectF(PAD + k * (width + PAD), PAD, width, H - 2 * PAD)
        p.setPen(QtGui.QPen(QtGui.QColor('#D8DEE7'), 1)); p.setBrush(QtCore.Qt.NoBrush); p.drawRoundedRect(box, 6, 6)
        start, end = item.get('start'), item.get('end')
        has_peak = isinstance(start, (int, float)) and isinstance(end, (int, float)) and end > start and item.get('area') is not None
        window = windows.get(element) or {}
        if has_peak:
            margin = max(6.0, 0.6 * (end - start))
            lo, hi = max(0.0, start - margin), min(n - 1.0, end + margin)
        elif isinstance(window.get('start'), (int, float)) and isinstance(window.get('end'), (int, float)):
            lo, hi = float(window['start']), float(min(n - 1, window['end']))
        else:
            lo, hi = 0.0, n - 1.0
        if hi - lo < 2:
            lo, hi = max(0.0, lo - 2), min(n - 1.0, hi + 2)
        if has_peak:  # vertical scale from the integrated peak itself; a large neighbour is cut off at the top
            pad = 0.15 * (end - start)
            segment = [signal[i] for i in range(int(math.floor(max(lo, start - pad))), int(math.ceil(min(hi, end + pad))) + 1)]
        else:
            segment = [signal[i] for i in range(int(math.floor(lo)), int(math.ceil(hi)) + 1)]
        ymin, ymax = min(segment), max(segment)
        if has_peak:
            for b in (item.get('baseline_left'), item.get('baseline_right')):
                if isinstance(b, (int, float)) and math.isfinite(b):
                    ymin, ymax = min(ymin, b), max(ymax, b)
        if ymax - ymin <= 0:
            ymax = ymin + 1
        ypad = 0.08 * (ymax - ymin); ymin -= ypad; ymax += ypad
        plot = QtCore.QRectF(box.left() + 62, box.top() + 62, box.width() - 76, box.height() - 112)

        def sx(x): return plot.left() + (x - lo) / (hi - lo) * plot.width()
        def sy(y): return plot.bottom() - (y - ymin) / (ymax - ymin) * plot.height()

        # title: element, area, reported value
        p.setFont(title_font); p.setPen(colour)
        p.drawText(QtCore.QRectF(box.left() + 12, box.top() + 8, box.width() - 24, 26), QtCore.Qt.AlignLeft, NAMES[element])
        p.setFont(small); p.setPen(QtGui.QColor('#334155'))
        reported = report_value(record, element)
        found = 'found ' if record.role == 'Calibration' else ''  # a standard's value is compared with its composition
        if item.get('reviewed_zero'):
            line = '0 (reported as zero after review)'
        elif isinstance(reported, (int, float)) and reported == 0 and report_value_convention(record, element):
            line = '0 (no peak)'
        elif isinstance(reported, (int, float)):
            line = f'{found}{reported:.4f} % w/w'
        else:
            line = 'no peak' if not has_peak else report_value_text(record, element)
        if has_peak and not item.get('reviewed_zero'):
            line += f"   ·   peak area {format_area(item.get('area'))}"
        p.drawText(QtCore.QRectF(box.left() + 12, box.top() + 34, box.width() - 24, 22), QtCore.Qt.AlignLeft, line)
        # axes
        p.setPen(QtGui.QPen(QtGui.QColor('#94A3B8'), 1))
        p.drawLine(QtCore.QPointF(plot.left(), plot.bottom()), QtCore.QPointF(plot.right(), plot.bottom()))
        p.drawLine(QtCore.QPointF(plot.left(), plot.top()), QtCore.QPointF(plot.left(), plot.bottom()))
        p.setPen(QtGui.QColor('#64748B'))
        for t in _figure_axes_ticks(lo, hi, 4):
            x = sx(t); p.drawLine(QtCore.QPointF(x, plot.bottom()), QtCore.QPointF(x, plot.bottom() + 4))
            p.drawText(QtCore.QRectF(x - 40, plot.bottom() + 5, 80, 18), QtCore.Qt.AlignHCenter, f'{t:g}')
        for t in _figure_axes_ticks(ymin, ymax, 4):
            y = sy(t)
            if plot.top() - 1 <= y <= plot.bottom() + 1:
                p.drawLine(QtCore.QPointF(plot.left() - 4, y), QtCore.QPointF(plot.left(), y))
                p.drawText(QtCore.QRectF(box.left() + 2, y - 9, 56, 18), QtCore.Qt.AlignRight | QtCore.Qt.AlignVCenter,
                           _figure_number(t, 3))
        p.drawText(QtCore.QRectF(plot.left(), box.bottom() - 20, plot.width(), 18), QtCore.Qt.AlignHCenter, 'detector point')
        p.setClipRect(plot)
        # integrated area (signal above the straight baseline) and the baseline
        if has_peak:
            bl, br = item.get('baseline_left'), item.get('baseline_right')
            bl = value_at(start) if not isinstance(bl, (int, float)) else float(bl)
            br = value_at(end) if not isinstance(br, (int, float)) else float(br)
            outline, baseline_line = figure_area_outline(item, start, end, value_at, bl, br)
            baseline_points = [QtCore.QPointF(sx(x), sy(y)) for x, y in baseline_line]
            polygon = QtGui.QPolygonF([QtCore.QPointF(sx(x), sy(y)) for x, y in outline])
            fill = QtGui.QColor(colour); fill.setAlpha(60)
            p.setPen(QtCore.Qt.NoPen); p.setBrush(fill); p.drawPolygon(polygon)
            p.setPen(QtGui.QPen(colour, 2)); p.setBrush(QtCore.Qt.NoBrush); p.drawPolyline(QtGui.QPolygonF(baseline_points))
        # signal
        p.setPen(QtGui.QPen(QtGui.QColor('#1F2937'), 1.6)); p.setBrush(QtCore.Qt.NoBrush)
        path = QtGui.QPainterPath(); first = True
        for i in range(int(math.floor(lo)), int(math.ceil(hi)) + 1):
            point = QtCore.QPointF(sx(i), sy(signal[i]))
            if first:
                path.moveTo(point); first = False
            else:
                path.lineTo(point)
        p.drawPath(path)
        if has_peak:
            p.setPen(QtGui.QPen(colour, 1.5)); p.setBrush(QtGui.QColor('white'))
            for x in (start, end):
                p.drawEllipse(QtCore.QPointF(sx(x), sy(value_at(x))), 5, 5)
        else:
            p.setPen(QtGui.QColor('#94A3B8'))
            p.drawText(plot, QtCore.Qt.AlignCenter, 'no integrated peak')
        p.setClipping(False)
    p.end()
    return _figure_png(image, QtCore), W, H


def figure_calibrations(project, preview, QtGui, QtCore):
    """The calibration curve of each element (2 × 2): standards, fitted line and equation, samples on the line."""
    calibrations = (preview or {}).get('calibrations') or {}
    if not calibrations:
        return None
    W, H = 1800, 1300
    image = QtGui.QImage(W, H, QtGui.QImage.Format_RGB32); image.fill(QtGui.QColor('white'))
    p = QtGui.QPainter(image); p.setRenderHint(QtGui.QPainter.Antialiasing)
    title_font = QtGui.QFont('Arial'); title_font.setPixelSize(22); title_font.setBold(True)
    small = QtGui.QFont('Arial'); small.setPixelSize(16)
    roles = {r.index: r for r in project.records}
    for k, element in enumerate(ELEMENTS):
        fit = calibrations.get(element) or {}
        colour = QtGui.QColor(FIGURE_COLORS[element])
        box = QtCore.QRectF(8 + (k % 2) * (W / 2), 8 + (k // 2) * (H / 2), W / 2 - 16, H / 2 - 16)
        p.setPen(QtGui.QPen(QtGui.QColor('#D8DEE7'), 1)); p.setBrush(QtCore.Qt.NoBrush); p.drawRoundedRect(box, 6, 6)
        p.setFont(title_font); p.setPen(colour)
        p.drawText(QtCore.QRectF(box.left() + 14, box.top() + 10, box.width() - 28, 30), QtCore.Qt.AlignLeft, NAMES[element] + ' calibration')
        points = [q for q in fit.get('points') or [] if isinstance(q.get('amount_mg'), (int, float))]
        slope, intercept = fit.get('slope'), fit.get('intercept') or 0.0
        samples = []
        if isinstance(slope, (int, float)) and slope:
            for index, rec in ((preview or {}).get('records') or {}).items():
                record = roles.get(int(index))
                item = (rec.get('elements') or {}).get(element) or {}
                if record is not None and record.role in ('Sample', 'Check') and isinstance(item.get('area'), (int, float)):
                    samples.append(((item['area'] - intercept) / slope, item['area']))
        xs = [q['amount_mg'] for q in points] + [s[0] for s in samples] + [0.0]
        ys = [q['area'] for q in points if isinstance(q.get('area'), (int, float))] + [s[1] for s in samples] + [0.0]
        p.setFont(small)
        if not points or len(ys) < 2:
            p.setPen(QtGui.QColor('#64748B'))
            p.drawText(box, QtCore.Qt.AlignCenter, 'No standards for this element in the run.')
            continue
        xmax, ymax = max(xs) * 1.08 or 1.0, max(ys) * 1.08 or 1.0
        xmin, ymin = min(0.0, min(xs)), min(0.0, min(ys))
        plot = QtCore.QRectF(box.left() + 96, box.top() + 92, box.width() - 120, box.height() - 150)

        def sx(x): return plot.left() + (x - xmin) / (xmax - xmin) * plot.width()
        def sy(y): return plot.bottom() - (y - ymin) / (ymax - ymin) * plot.height()

        used = sum(1 for q in points if q.get('included', True) and isinstance(q.get('area'), (int, float)))
        words = calibration_lines(fit, element)
        if words:
            equation = words[0].split(': ', 1)[1] + '   ·   ' + words[1]
            detail = words[2].replace(f'{used} standard', f'{used} of {len(points)} standard')
        else:
            equation, detail = 'No curve', 'No usable standard'
        p.setPen(QtGui.QColor('#334155'))
        p.drawText(QtCore.QRectF(box.left() + 14, box.top() + 42, box.width() - 28, 22), QtCore.Qt.AlignLeft, equation)
        p.setPen(QtGui.QColor('#64748B'))
        p.drawText(QtCore.QRectF(box.left() + 14, box.top() + 64, box.width() - 28, 22), QtCore.Qt.AlignLeft, detail)
        p.setPen(QtGui.QPen(QtGui.QColor('#94A3B8'), 1))
        p.drawLine(QtCore.QPointF(plot.left(), plot.bottom()), QtCore.QPointF(plot.right(), plot.bottom()))
        p.drawLine(QtCore.QPointF(plot.left(), plot.top()), QtCore.QPointF(plot.left(), plot.bottom()))
        p.setPen(QtGui.QColor('#64748B'))
        for t in _figure_axes_ticks(xmin, xmax, 5):
            x = sx(t); p.drawLine(QtCore.QPointF(x, plot.bottom()), QtCore.QPointF(x, plot.bottom() + 4))
            p.drawText(QtCore.QRectF(x - 45, plot.bottom() + 6, 90, 20), QtCore.Qt.AlignHCenter, f'{t:g}')
        for t in _figure_axes_ticks(ymin, ymax, 5):
            y = sy(t); p.drawLine(QtCore.QPointF(plot.left() - 4, y), QtCore.QPointF(plot.left(), y))
            p.drawText(QtCore.QRectF(box.left() + 4, y - 10, 86, 20), QtCore.Qt.AlignRight | QtCore.Qt.AlignVCenter, _figure_number(t, 3))
        p.drawText(QtCore.QRectF(plot.left(), box.bottom() - 26, plot.width(), 22), QtCore.Qt.AlignHCenter,
                   NAMES[element].lower() + ' in the portion (mg)')
        p.save(); p.translate(box.left() + 14, plot.center().y()); p.rotate(-90)
        p.drawText(QtCore.QRectF(-80, -10, 160, 20), QtCore.Qt.AlignHCenter, 'peak area'); p.restore()
        p.setClipRect(plot.adjusted(-8, -8, 8, 8))
        if isinstance(slope, (int, float)):
            p.setPen(QtGui.QPen(colour, 2.2))
            p.drawLine(QtCore.QPointF(sx(xmin), sy(intercept + slope * xmin)), QtCore.QPointF(sx(xmax), sy(intercept + slope * xmax)))
        p.setPen(QtGui.QPen(QtGui.QColor('#A16207'), 1.2)); p.setBrush(QtGui.QColor('#FACC15'))
        for x, y in samples:
            q = QtCore.QPointF(sx(x), sy(y)); d = 6
            p.drawPolygon(QtGui.QPolygonF([q + QtCore.QPointF(0, -d), q + QtCore.QPointF(d, 0), q + QtCore.QPointF(0, d), q + QtCore.QPointF(-d, 0)]))
        p.setClipping(False)  # standards lie inside the plot; their names may use the whole panel
        taken = []
        metrics = QtGui.QFontMetricsF(small)
        for q in points:
            area = q.get('area')
            y = sy(area) if isinstance(area, (int, float)) else plot.bottom()
            centre = QtCore.QPointF(sx(q['amount_mg']), y)
            if q.get('included', True) and isinstance(area, (int, float)):
                p.setPen(QtGui.QPen(QtGui.QColor('#0F172A'), 1.2)); p.setBrush(colour); p.drawEllipse(centre, 8, 8)
            else:
                p.setPen(QtGui.QPen(QtGui.QColor('#B91C1C'), 2)); p.setBrush(QtGui.QColor('white')); p.drawEllipse(centre, 8, 8)
                p.drawLine(centre + QtCore.QPointF(-6, -6), centre + QtCore.QPointF(6, 6))
                p.drawLine(centre + QtCore.QPointF(-6, 6), centre + QtCore.QPointF(6, -6))
            p.setPen(QtGui.QColor('#334155'))
            label = str(q.get('name') or q.get('id')) + ('' if q.get('included', True) else ' (excluded)')
            w = metrics.horizontalAdvance(label) + 4
            # first free place around the point, inside the panel, not on another name
            for dx, dy in ((12, -24), (12, 4), (-12 - w, -24), (-12 - w, 4), (12, -46), (-12 - w, -46), (12, 26), (-12 - w, 26)):
                rect = QtCore.QRectF(centre.x() + dx, centre.y() + dy, w, 20)
                if box.adjusted(4, 4, -4, -4).contains(rect) and not any(rect.intersects(t) for t in taken):
                    break
            taken.append(rect)
            p.drawText(rect, QtCore.Qt.AlignLeft, label)
        p.setClipping(False)
    p.end()
    return _figure_png(image, QtCore), W, H


def report_figures(project):
    """[(title, caption, png, width, height)] for the Word report; None when figures cannot be drawn here."""
    if not any(_processing_trace(r) for r in project.records):
        return []
    try:
        QtGui, QtCore = _figure_qt()
        preview, basis = _figure_basis(project)
        applied = preview is (project.processing or {}).get('active_preview')
        saved_preview = processing_saved_preview(project) if applied else None
    except Exception:
        return None
    figures = []
    calibration = figure_calibrations(project, preview, QtGui, QtCore)
    if calibration:
        figures.append(('Calibration curves', basis + ' Filled circles: standards in the curve; red crossed circles: '
                        'excluded or without a usable peak; yellow diamonds: samples and check material on the curve.') + calibration)
    order = {'Calibration': 0, 'Check': 1, 'Sample': 2}
    for record in sorted((r for r in project.records if r.role in order and _processing_trace(r)),
                         key=lambda r: (order[r.role], project.records.index(r))):
        drawn = figure_chromatogram(record, preview, QtGui, QtCore, saved_preview)
        if drawn:
            role = {'Calibration': 'standard', 'Check': 'check material', 'Sample': 'sample'}[record.role]
            mass = f'{record.weight_mg:.3f} mg' if isinstance(record.weight_mg, (int, float)) else 'mass not recorded'
            figures.append((f'{record.name} ({role}, {mass})',
                            'Each panel shows one element: detector signal, integrated area (shaded) above the straight '
                            'baseline from start to end point (circles), and the reported value.') + drawn)
    return figures




# ---------------------------------------------------------------------------------------------------------------
# Detailed explanations.docx, written for a human reader (CHNSetti 1.0.0): summary → results → calibration →
# analyst's changes → how it was calculated → open points → chromatograms → source files.
# Standard library only (plus Qt for the figures).
# ---------------------------------------------------------------------------------------------------------------
REPORT_MODELS = {
    'averaged_k': ('K factor through the origin',
                   'For each element: peak area = K × element mass, where K is the average of the standards\' ratios of peak area to element mass.'),
    'origin_ols': ('least-squares line through the origin', 'For each element: peak area = K × element mass, with K fitted by least squares through the origin.'),
    'linear': ('least-squares line with intercept', 'For each element: peak area = K × element mass + b, fitted by least squares.'),
}
REPORT_ACTIONS = {
    'identification_confirmed': 'Sample roles and groups confirmed', 'settings_confirmed': 'Calculation rules confirmed',
    'source_verified': 'Source data verified', 'native_processing_applied': 'CHNSetti integration applied to the report',
    'native_processing_restored': 'Instrument values restored', 'reviewed_zero': 'Value reported as zero after review',
    'measurements_reviewed': 'Measurement decision recorded', 'portions_grouped': 'Portions grouped',
    'grouping_suggestions_applied': 'Suggested grouping applied', 'reference_correction_applied': 'Reference correction applied',
    'reference_correction_removed': 'Reference correction removed', 'corrected_source_imported': 'Corrected source imported',
    'project_migrated': 'Project converted from an earlier version', 'saved_source_bounds_selected': 'Instrument boundaries selected',
}


def _report_date(text):
    """'2026-11-21T11:31:13+00:00' or '2026-11-17' → '21 Nov 2026' (local time for timestamps)."""
    try:
        if 'T' in str(text):
            moment = datetime.fromisoformat(str(text).replace('Z', '+00:00')).astimezone()
            return moment.strftime('%d %b %Y, %H:%M').lstrip('0')
        return datetime.strptime(str(text)[:10], '%Y-%m-%d').strftime('%d %b %Y').lstrip('0')
    except (TypeError, ValueError):
        return str(text or '')


def _report_fixed(value, digits):
    return '—' if value is None or not isinstance(value, (int, float)) or not math.isfinite(value) else f'{value:.{digits}f}'


def report_range_note(project, record, element, preview):
    """Outside the standards' range? Same rule as step 6: reported % × portion mass against the standards' amounts."""
    value = report_value(record, element)
    if not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0 or not record.weight_mg:
        return ''
    applied = bool(_selected_processing(record, element))
    source = (project.processing or {}).get('active_preview') if applied else preview
    fit = ((source or {}).get('calibrations') or {}).get(element) or {}
    amounts = [float(p['amount_mg']) for p in fit.get('points') or []
               if isinstance(p.get('amount_mg'), (int, float)) and p['amount_mg'] > 0
               and (not applied or (p.get('included', True) and isinstance(p.get('area'), (int, float))))]
    if not amounts:
        return ''
    amount = float(value) / 100 * float(record.weight_mg)
    if min(amounts) <= amount <= max(amounts):
        return ''
    return 'below' if amount < min(amounts) else 'above'


def _report_open_points(project):
    """Open points in plain words, one line per measurement."""
    readiness = report_readiness(project)
    lines, per_element = [], {}
    names = {r.name for r in project.records}
    for message in readiness['blockers']:
        head, _, rest = message.partition(', ')
        element = rest[:1] if rest[1:2] == ':' else ''
        if head in names and element in ELEMENTS:
            per_element.setdefault(element, []).append(head)
        elif message.startswith('Confirm sample roles and groups'):
            count = message.count(',') + 1
            lines.append(f'Confirm the sample roles and groups of {count} measurement' + ('' if count == 1 else 's') + ' (step 2, Identification).')
        elif message.startswith(('Record source verification', 'Sign off the results')):
            lines.append('Sign off the results as final (step 7, Generate).')
        else:
            lines.append(message)
    for element in ELEMENTS:
        if per_element.get(element):
            lines.append(f'{NAMES[element]} waiting for a decision (peak assignment or integration, steps 5 and 6): '
                         + ', '.join(dict.fromkeys(per_element[element])) + '.')
    return readiness, lines


def _write_report_docx(project: Project, path):
    from xml.sax.saxutils import escape as xe
    groups = compute_results(project, reporting=True)
    native = any(_processing_trace(r) for r in project.records)
    preview, basis_text = (None, '')
    if native:
        try:
            preview, basis_text = _figure_basis(project)
        except Exception:
            preview, basis_text = None, ''
    applied = any(_selected_processing(r, e) for r in project.records for e in ELEMENTS)
    body, media = [], []

    def clean(value):
        return xe(''.join(c for c in str(value if value is not None else '') if c in '\t\n\r' or ord(c) >= 32))

    def run(text, bold=False, italic=False, size=None, colour=None, sup=False, mono=False):
        props = ('<w:rFonts w:ascii="Consolas" w:hAnsi="Consolas"/>' if mono else '') + ('<w:b/>' if bold else '') + \
                ('<w:i/>' if italic else '') + (f'<w:color w:val="{colour}"/>' if colour else '') + \
                (f'<w:sz w:val="{size}"/>' if size else '') + ('<w:vertAlign w:val="superscript"/>' if sup else '')
        return '<w:r>' + (f'<w:rPr>{props}</w:rPr>' if props else '') + f'<w:t xml:space="preserve">{clean(text)}</w:t></w:r>'

    def para(*runs, style='Normal', keep=False, after=None, align=None):
        props = f'<w:pStyle w:val="{style}"/>' + ('<w:keepNext/>' if keep else '') + \
                (f'<w:spacing w:after="{after}"/>' if after is not None else '') + (f'<w:jc w:val="{align}"/>' if align else '')
        body.append(f'<w:p><w:pPr>{props}</w:pPr>' + ''.join(r if r.startswith('<w:r>') else run(r) for r in runs) + '</w:p>')

    def heading(text, level=1):
        para(run(text), style=f'Heading{level}', keep=True)

    def bullet(*runs):
        para(run('•  '), *runs, style='Bullet')

    def page_break():
        body.append('<w:p><w:r><w:br w:type="page"/></w:r></w:p>')

    def table(columns, rows, size=18, fills=None, header=True):
        """columns: [(header, width in twips, align)]; rows: list of lists of str or run lists."""
        grid = ''.join(f'<w:gridCol w:w="{w}"/>' for _, w, _ in columns)
        out = []
        head = ''.join(f'<w:tc><w:tcPr><w:tcW w:w="{w}" w:type="dxa"/><w:shd w:val="clear" w:fill="20334B"/></w:tcPr>'
                       f'<w:p><w:pPr><w:spacing w:after="0"/><w:jc w:val="{a}"/></w:pPr>{run(h, bold=True, colour="FFFFFF", size=size)}</w:p></w:tc>'
                       for h, w, a in columns)
        if header:
            out.append('<w:tr><w:trPr><w:tblHeader/></w:trPr>' + head + '</w:tr>')
        for i, row in enumerate(rows):
            fill = (fills[i] if fills and fills[i] else ('F3F6FA' if i % 2 else 'FFFFFF'))
            cells = []
            for (h, w, a), cell in zip(columns, row):
                content = ''.join(cell) if isinstance(cell, list) else run(cell, size=size)
                cells.append(f'<w:tc><w:tcPr><w:tcW w:w="{w}" w:type="dxa"/><w:shd w:val="clear" w:fill="{fill}"/></w:tcPr>'
                             f'<w:p><w:pPr><w:spacing w:after="0"/><w:jc w:val="{a}"/></w:pPr>{content}</w:p></w:tc>')
            out.append('<w:tr><w:trPr><w:cantSplit/></w:trPr>' + ''.join(cells) + '</w:tr>')
        border = ''.join(f'<w:{side} w:val="single" w:sz="4" w:color="D8DEE7"/>' for side in ('top', 'left', 'bottom', 'right', 'insideH', 'insideV'))
        body.append('<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders>' + border + '</w:tblBorders>'
                    '<w:tblCellMar><w:left w:w="80" w:type="dxa"/><w:right w:w="80" w:type="dxa"/></w:tblCellMar></w:tblPr>'
                    f'<w:tblGrid>{grid}</w:tblGrid>' + ''.join(out) + '</w:tbl>')
        para('', after=60)

    def figure(png, width, height, caption):
        media.append(png); number = len(media)
        cx = 6264000; cy = int(cx * height / width)
        body.append('<w:p><w:pPr><w:keepNext/><w:spacing w:after="40"/></w:pPr><w:r><w:drawing>'
                    '<wp:inline distT="0" distB="0" distL="0" distR="0">'
                    f'<wp:extent cx="{cx}" cy="{cy}"/><wp:docPr id="{number}" name="Figure {number}"/>'
                    '<wp:cNvGraphicFramePr><a:graphicFrameLocks noChangeAspect="1"/></wp:cNvGraphicFramePr>'
                    '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic>'
                    f'<pic:nvPicPr><pic:cNvPr id="{number}" name="figure{number}.png"/><pic:cNvPicPr/></pic:nvPicPr>'
                    f'<pic:blipFill><a:blip r:embed="rIdFigure{number}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>'
                    f'<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="{cx}" cy="{cy}"/></a:xfrm>'
                    '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic>'
                    '</wp:inline></w:drawing></w:r></w:p>')
        para(run(f'Figure {number}. ', bold=True, size=17, colour='475569'), run(caption, italic=True, size=17, colour='475569'), after=200)

    records = {r.index: r for r in project.records}
    samples = [g for g in groups if g.role == 'Sample']
    checks = [g for g in groups if g.role == 'Check']
    standards = [r for r in project.records if r.role == 'Calibration']
    dates = sorted({str(r.date)[:10] for r in project.records if getattr(r, 'date', '')})
    readiness, open_points = _report_open_points(project)
    calibrations = (preview or {}).get('calibrations') or {}

    # ------------------------------------------------------------------ title and status
    para(run('CHNS elemental analysis — ' + (project.settings.run_name or 'run')), style='Title')
    para(run(APP_DEVELOPER, colour='475569'))
    facts = []
    if dates:
        facts.append('Analysed ' + (_report_date(dates[0]) if len(dates) == 1 else f'{_report_date(dates[0])} – {_report_date(dates[-1])}'))
    if native:
        facts.append('Thermo Scientific Flash 2000 (CHNS-O), Eager 300')
    facts.append(f'Report made {_report_date(utc_now())} with {APP_NAME} {APP_VERSION}')
    para(run('  ·  '.join(facts), colour='475569', size=18), after=200)
    if readiness['ready']:
        status = [run('Reviewed. ', bold=True, colour='166534'),
                  run(f"Source verified by {project.source_review.get('reviewer', '')} on {_report_date(project.source_review.get('time_utc', ''))}.")]
        fill = 'ECFDF5'
    else:
        status = [run('Not yet reviewed. ', bold=True, colour='9A3412'),
                  run(f'{len(open_points)} open point' + ('' if len(open_points) == 1 else 's') + ' (section 6). '
                      'The numbers below are complete, but not yet approved.')]
        fill = 'FFF7ED'
    body.append('<w:tbl><w:tblPr><w:tblW w:w="9866" w:type="dxa"/><w:tblBorders><w:top w:val="single" w:sz="4" w:color="FED7AA"/>'
                '<w:left w:val="single" w:sz="4" w:color="FED7AA"/><w:bottom w:val="single" w:sz="4" w:color="FED7AA"/>'
                '<w:right w:val="single" w:sz="4" w:color="FED7AA"/></w:tblBorders></w:tblPr><w:tblGrid><w:gridCol w:w="9866"/></w:tblGrid>'
                f'<w:tr><w:tc><w:tcPr><w:shd w:val="clear" w:fill="{fill}"/></w:tcPr><w:p><w:pPr><w:spacing w:before="80" w:after="80"/></w:pPr>'
                + ''.join(status) + '</w:p></w:tc></w:tr></w:tbl>')
    if getattr(project, 'demo', False):
        para(run(DEMO_WARNING if 'invented' in ' '.join(project.input_warnings) else
                 'SIMULATED DATA — this example contains no laboratory measurements.', bold=True, colour='9A3412'), after=60)
    para('', after=60)

    # ------------------------------------------------------------------ 1. summary
    heading('1. Summary')
    zero_cells = sum(1 for g in samples + checks for i in g.indices for e in ELEMENTS
                     if report_value(records[i], e) == 0 and report_value_convention(records[i], e))
    outside = sum(1 for g in samples for i in g.indices for e in ELEMENTS if report_range_note(project, records[i], e, preview))
    portions = sum(len(g.indices) for g in samples)
    summary = [('Samples', f'{len(samples)} sample' + ('' if len(samples) == 1 else 's') + f', {portions} weighed portions'),
               ('Standards', ', '.join(dict.fromkeys(r.name for r in standards)) or '—'),
               ('Check material', ', '.join(g.name for g in checks) or '—')]
    if native:
        if applied:
            last = next((d for d in reversed(project.decisions) if d.get('action') == 'native_processing_applied'), {})
            summary.append(('Integration', f"CHNSetti, applied by {last.get('reviewer', '')} on {_report_date(last.get('time_utc', ''))}"))
        else:
            summary.append(('Integration', 'as saved by the instrument software (Eager 300), unchanged'))
        model = next((REPORT_MODELS.get(f.get('model'), (f.get('model'),))[0] for f in calibrations.values() if f.get('model')), '')
        if model:
            summary.append(('Calibration', model + ', from the standards of this run'))
    else:
        summary.append(('Values', 'imported from ' + (project.input_format or 'a spreadsheet') + ' (' + os.path.basename(str(project.source_name or '')) + ')'))
    if zero_cells:
        summary.append(('Reported as 0', f'{zero_cells} value' + ('' if zero_cells == 1 else 's') + ' with no peak (marked ᵃ)'))
    if outside:
        summary.append(('Extrapolated', f'{outside} portion value' + ('' if outside == 1 else 's') + ' outside the range of the standards (marked ᵇ in the portions table)'))
    table([('', 2600, 'left'), ('', 7266, 'left')], [[[run(k, bold=True, size=18)], v] for k, v in summary], header=False)

    # ------------------------------------------------------------------ 2. results
    heading('2. Results (% w/w)')
    para('Mean ± standard deviation of the weighed portions of each sample. The Excel report "CHNS results - report.xlsx" '
         'holds the same numbers with full precision.')

    def marked(value_runs, zero, extrapolated):
        out = list(value_runs)
        marks = ('a' if zero else '') + ('b' if extrapolated else '')
        if marks:
            out.append(run(' ' + ','.join(marks), sup=True, colour='9A3412', size=16))
        return out

    rows = []
    for g in samples:
        members = [records[i] for i in g.indices]
        row = [[run(g.name, bold=True, size=18)], str(len(members))]
        for e in ELEMENTS:
            mean, sd = g.means.get(e), g.sds.get(e)
            zero = any(report_value(r, e) == 0 and report_value_convention(r, e) for r in members)
            text = _report_fixed(mean, 4) + ('' if sd is None else ' ± ' + _report_fixed(sd, 4))
            row.append(marked([run(text, size=18)], zero, False))
        rows.append(row)
    if rows:
        table([('Sample', 2266, 'left'), ('Portions', 900, 'center')] + [(NAMES[e], 1675, 'center') for e in ELEMENTS], rows)
    zero_note = [run('a', sup=True, colour='9A3412'), run(' includes portions with no peak, reported as 0 (laboratory convention: 0, not NQ). '
                 'This is not a measured value; the zero counts in the mean and standard deviation.')]
    if zero_cells:
        para(*zero_note, style='Note')
    if any(g.means.get(e) is None for g in samples for e in ELEMENTS):
        para(run('— not reported: the value is waiting for a decision (section 6).'), style='Note')
    heading('Individual portions', 2)
    rows = []
    for g in samples:
        for i in g.indices:
            r = records[i]
            row = [r.name, _report_fixed(r.weight_mg, 3)]
            for e in ELEMENTS:
                value = report_value(r, e)
                text = _report_fixed(value, 4) if value is not None else report_value_text(r, e)
                row.append(marked([run(text, size=17)], value == 0 and bool(report_value_convention(r, e)),
                                  bool(report_range_note(project, r, e, preview))))
            rows.append(row)
    if rows:
        table([('Portion', 2266, 'left'), ('Mass (mg)', 900, 'center')] + [(NAMES[e], 1675, 'center') for e in ELEMENTS], rows, size=17)
    if zero_cells:
        para(run('a', sup=True, colour='9A3412'), run(' no peak, reported as 0 (laboratory convention).'), style='Note')
    if outside:
        para(run('b', sup=True, colour='9A3412'), run(' outside the range of the standards: the amount of the element in this portion is below '
             'the lowest (or above the highest) standard, so the result is extrapolated from the calibration.'), style='Note')
    held = sorted({report_value_text(records[i], e) for g in samples for i in g.indices for e in ELEMENTS if report_value(records[i], e) is None})
    if 'Failed' in held:
        para(run('Failed: left out of the mean — the portion did not burn, or the element is missing in this portion '
                 'while the other portions of the sample contain it (section 6).'), style='Note')
    held = [h for h in held if h != 'Failed']
    if held:
        para(run(' / '.join(held) + ': not reported, waiting for a decision (section 6).'), style='Note')
    if checks:
        heading('Check material', 2)
        para('Measured as an unknown to check the calibration; not used in it. The certified values are those of the batch '
             'chosen in CHNSetti (' + str(project.settings.reference_table) + ').')
        rows = []
        for g in checks:
            for i in g.indices:
                r = records[i]
                rows.append([r.name, _report_fixed(r.weight_mg, 3)] + [
                    _report_fixed(report_value(r, e), 4) if report_value(r, e) is not None else report_value_text(r, e) for e in ELEMENTS])
            material = check_material(g.name) or next((check_material(records[i].name) for i in g.indices if check_material(records[i].name)), '')
            certified = reference_values(project).get(material) or {}
            if certified:
                rows.append(['Certificate, ' + project.settings.reference_table, ''] +
                            [_report_fixed(certified.get(e), 2) if certified.get(e) is not None else '—' for e in ELEMENTS])
        table([('Check', 2266, 'left'), ('Mass (mg)', 900, 'center')] + [(NAMES[e], 1675, 'center') for e in ELEMENTS], rows, size=17)

    # ------------------------------------------------------------------ 3. calibration
    if native and calibrations:
        heading('3. Calibration')
        model = next((f.get('model') for f in calibrations.values() if f.get('model')), '')
        para(REPORT_MODELS.get(model, ('', ''))[1] + ' The element mass in a standard is its weighed mass × its composition; '
             'the peak area is in detector units (it has no physical unit and only matters relative to the standards). '
             + ('The curves are those applied to the report.' if applied else
                'The report uses the instrument\'s own calibration; the curves here are computed from the standards\' saved areas, for comparison.'))
        rows = []
        for e in ELEMENTS:
            fit = calibrations.get(e) or {}
            points = fit.get('points') or []
            used = [p for p in points if p.get('included', True) and isinstance(p.get('area'), (int, float))]
            slope, intercept = fit.get('slope'), fit.get('intercept') or 0.0
            k = (format_factor(slope) + (f', b = {format_factor(intercept)}' if intercept else '')) if isinstance(slope, (int, float)) else 'no curve'
            excluded = [f"{p.get('name')}" + (f" ({p.get('reason')})" if p.get('reason') else '') for p in points if not p.get('included', True)]
            recoveries = [p['recovery_pct'] for p in used if isinstance(p.get('recovery_pct'), (int, float))]
            spread = (f'{min(recoveries):.1f} – {max(recoveries):.1f} %' if len(recoveries) > 1 else
                      f'{recoveries[0]:.1f} %' if recoveries else '—')
            rows.append([[run(NAMES[e], bold=True, size=18)], k, f'{len(used)} of {len(points)}', spread, '; '.join(excluded) or '—'])
        table([('Element', 1400, 'left'), ('K (peak area per mg)', 2300, 'left'), ('Standards used', 1300, 'center'),
               ('Recoveries', 1800, 'center'), ('Excluded (reason)', 3066, 'left')], rows)
        heading('Recovery of the standards', 2)
        para('Result of each standard with the curve, divided by its composition. Close to 100 % means the standards agree.')
        rows = []
        for r in standards:
            row = [r.name, _report_fixed(r.weight_mg, 3)]
            for e in ELEMENTS:
                point = next((p for p in (calibrations.get(e) or {}).get('points') or [] if str(p.get('id')) == str(r.index)), None)
                if point is None:
                    row.append('—')
                elif not point.get('included', True):
                    row.append([run('excluded', italic=True, size=17, colour='64748B')])
                elif isinstance(point.get('recovery_pct'), (int, float)):
                    row.append(f"{point['recovery_pct']:.1f} %")
                else:
                    row.append('no peak')
            rows.append(row)
        table([('Standard', 2266, 'left'), ('Mass (mg)', 900, 'center')] + [(NAMES[e], 1675, 'center') for e in ELEMENTS], rows, size=17)
        try:
            QtGui, QtCore = _figure_qt()
            drawn = figure_calibrations(project, preview, QtGui, QtCore)
        except Exception:
            drawn = None
        if drawn:
            figure(drawn[0], drawn[1], drawn[2], 'Calibration curves. Filled circles: standards in the curve; red crossed circles: excluded '
                   'or without a usable peak; yellow diamonds: samples and check material on the line.')

    # ------------------------------------------------------------------ 4. analyst's changes
    heading(('4' if native else '3') + '. Changes made by the analyst')
    if native and not applied:
        para('None to the integration: the report uses the instrument\'s integration (Eager 300) unchanged.')
    if native and applied:
        last = next((d for d in reversed(project.decisions) if d.get('action') == 'native_processing_applied'), {})
        para(run('CHNSetti\'s integration was applied to the report ', bold=True),
             run(f"by {last.get('reviewer', '')} on {_report_date(last.get('time_utc', ''))}. Reason: {last.get('reason', '')}"))
        actions = (last.get('actions') if isinstance(last.get('actions'), list) else None) or ((project.processing or {}).get('active_preview') or {}).get('actions') or []
        for action in actions:
            name = getattr(records.get(action.get('index')), 'name', '') if action.get('index') is not None else ''
            element = NAMES.get(action.get('element'), action.get('element') or '').lower()
            kind = action.get('action')
            if kind == 'peak_edited':
                bullet(f"{name}, {element}: start and end set to {point_text(action.get('start'))}–{point_text(action.get('end'))}.")
            elif kind == 'calibration_point_changed':
                standard = next((p.get('name') for p in ((calibrations.get(action.get('element')) or {}).get('points') or [])
                                 if str(p.get('id')) == str(action.get('point_id'))), action.get('point_id'))
                bullet(f"{standard} {'restored to' if action.get('included') else 'excluded from'} the {element} curve"
                       + (f": {action.get('reason')}" if action.get('reason') else '') + '.')
            elif kind == 'reviewed_zero':
                bullet(f"{name}, {element}: reported as zero after review" + (f": {action.get('reason')}" if action.get('reason') else '') + '.')
            elif kind:
                bullet(f"{name + ', ' if name else ''}{element + ': ' if element else ''}{kind.replace('_', ' ')}.")
        if not actions:
            para('The automatic integration was applied without manual edits.')
    others = [d for d in project.decisions if d.get('action') not in ('native_method_import', 'native_processing_applied')]
    if others:
        rows = [[_report_date(d.get('time_utc', '')), str(d.get('reviewer', '') or ''),
                 REPORT_ACTIONS.get(d.get('action'), str(d.get('action', '')).replace('_', ' ').capitalize()),
                 str(d.get('reason', '') or d.get('note', '') or '')] for d in others]
        table([('When', 1900, 'left'), ('Who', 1700, 'left'), ('What', 3000, 'left'), ('Why', 3266, 'left')], rows, size=17)
    elif not native:
        para('None recorded.')

    # ------------------------------------------------------------------ 5. how it was calculated
    heading(('5' if native else '4') + '. How the results were calculated')
    if native and applied:
        baseline_method = ((project.processing.get('active_preview') or {}).get('settings') or {}).get('baseline_method', 'linear')
        if baseline_method == 'linear':
            bullet('Peak area: the detector signal above a straight baseline from the start point to the end point of the peak '
                   '(trapezoid rule on the stored signal; points between two detector readings are interpolated linearly).')
        else:
            bullet(f'Peak area: the detector signal above a fitted baseline ({baseline_method}) between the start point and the end '
                   'point of the peak (trapezoid rule on the stored signal; points between two detector readings are interpolated linearly).')
        if any(isinstance((fit or {}).get('intercept'), (int, float)) and fit.get('intercept') for fit in calibrations.values()):
            bullet('Element mass in a portion = (area − b) ÷ K, where b is the intercept of the calibration (section 3; it includes '
                   'a supplied blank area). Result (% w/w) = element mass ÷ weighed portion mass × 100.')
        else:
            bullet('Element mass in a portion = area ÷ K (section 3). Result (% w/w) = element mass ÷ weighed portion mass × 100.')
    elif native:
        bullet('The results are those calculated by the instrument software (Eager 300) from its saved integration and calibration.')
    else:
        bullet('The results are the values in the imported file; CHNSetti does not recalculate them.')
    bullet('Each sample was weighed and burnt as separate portions (normally three). Mean = average of the portions; '
           'standard deviation with n − 1 (as Excel STDEV.S).')
    bullet('No peak → 0 (laboratory convention); such zeros count in the mean and standard deviation and are marked ᵃ.')
    bullet('Every change has a reviewer and a reason (section ' + ('4' if native else '3') + '). The only automatic choice is the '
           'default choice of standards: a standard left out to bring the check material closer to its certificate is marked '
           '“Chosen automatically” with its reason, and enters the report only when the integration is applied.')
    if project.standard_correction:
        bullet('A reference correction is applied; its profile and offsets are in the Detailed calculations workbook.')
    bullet('Every input, intermediate value and decision is listed in "Detailed calculations.xlsx" and in the project file.')

    # ------------------------------------------------------------------ 6. open points
    heading(('6' if native else '5') + '. Open points')
    if open_points:
        for line in open_points[:12]:
            bullet(line)
        if len(open_points) > 12:
            bullet(f'… and {len(open_points) - 12} more (Detailed calculations, sheet "Quality review").')
    else:
        para('None.')

    # ------------------------------------------------------------------ 7. chromatograms
    figures = []
    if native:
        try:
            QtGui, QtCore = _figure_qt()
            order = {'Calibration': 0, 'Check': 1, 'Sample': 2}
            saved_preview = processing_saved_preview(project) if applied else None
            for record in sorted((r for r in project.records if r.role in order and _processing_trace(r)),
                                 key=lambda r: (order[r.role], project.records.index(r))):
                drawn = figure_chromatogram(record, preview, QtGui, QtCore, saved_preview)
                if drawn:
                    figures.append((record, drawn))
        except Exception:
            figures = None
    if figures:
        page_break()
        heading('7. Chromatograms')
        para(('Integration applied to the report. ' if applied else 'Integration saved by the instrument (Eager 300), as reported. ') +
             'One figure per measurement; each panel shows one element: the detector signal, the integrated area (shaded) above the '
             'straight baseline from the start point to the end point (circles), and the reported value.')
        for record, drawn in figures:
            role = {'Calibration': 'standard', 'Check': 'check material', 'Sample': 'sample'}[record.role]
            figure(drawn[0], drawn[1], drawn[2], f'{record.name} — {role}, {_report_fixed(record.weight_mg, 3)} mg')
    elif figures is None:
        para('The chromatograms could not be drawn on this computer; all numbers above are complete.')

    # ------------------------------------------------------------------ appendix: source files
    page_break()
    heading('Appendix. Source files')
    para('SHA-256 fingerprints identify the exact files that were read. Changing a file changes its fingerprint.')
    rows = []
    for item in project.source_files or []:
        name = os.path.basename(str(item.get('path') or item.get('name') or ''))
        rows.append([[run(name, size=15)], [run(str(item.get('role') or item.get('kind') or ''), size=15)],
                     [run(str(item.get('sha256') or ''), mono=True, size=13)]])
    if rows:
        table([('File', 3000, 'left'), ('Contents', 2000, 'left'), ('SHA-256', 4866, 'left')], rows, size=15)
    else:
        para(f'{os.path.basename(str(project.source_name or ""))}: {project.source_sha256 or ""}')
    warnings = list(dict.fromkeys(project.input_warnings or []))
    if warnings:
        heading('Notes from reading the files', 2)
        for note in warnings:
            para(run(note, size=17, colour='475569'), style='Note')

    # ------------------------------------------------------------------ package
    document = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'
        ' xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"'
        ' xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"'
        ' xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"'
        ' xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>' + ''.join(body) +
        '<w:sectPr><w:footerReference w:type="default" r:id="rIdFooter"/><w:pgSz w:w="11906" w:h="16838"/>'
        '<w:pgMar w:top="1020" w:bottom="1020" w:left="1020" w:right="1020" w:footer="500"/></w:sectPr></w:body></w:document>')
    footer = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<w:ftr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:p><w:pPr><w:jc w:val="center"/></w:pPr>'
        f'<w:r><w:rPr><w:color w:val="94A3B8"/><w:sz w:val="16"/></w:rPr><w:t xml:space="preserve">{clean(project.settings.run_name or "")}  ·  {APP_NAME} {APP_VERSION}  ·  page </w:t></w:r>'
        '<w:r><w:rPr><w:color w:val="94A3B8"/><w:sz w:val="16"/></w:rPr><w:fldChar w:fldCharType="begin"/></w:r>'
        '<w:r><w:rPr><w:color w:val="94A3B8"/><w:sz w:val="16"/></w:rPr><w:instrText xml:space="preserve"> PAGE </w:instrText></w:r>'
        '<w:r><w:rPr><w:color w:val="94A3B8"/><w:sz w:val="16"/></w:rPr><w:fldChar w:fldCharType="end"/></w:r></w:p></w:ftr>')
    styles = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
        '<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:color w:val="1F2937"/>'
        '<w:sz w:val="20"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after="100" w:line="264" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults>'
        '<w:style w:type="paragraph" w:styleId="Normal" w:default="1"><w:name w:val="Normal"/></w:style>'
        '<w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:pPr><w:spacing w:after="60"/></w:pPr>'
        '<w:rPr><w:b/><w:color w:val="20334B"/><w:sz w:val="36"/></w:rPr></w:style>'
        '<w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:pPr><w:keepNext/><w:spacing w:before="320" w:after="120"/>'
        '<w:outlineLvl w:val="0"/></w:pPr><w:rPr><w:b/><w:color w:val="20334B"/><w:sz w:val="28"/></w:rPr></w:style>'
        '<w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:pPr><w:keepNext/><w:spacing w:before="200" w:after="80"/>'
        '<w:outlineLvl w:val="1"/></w:pPr><w:rPr><w:b/><w:color w:val="20334B"/><w:sz w:val="22"/></w:rPr></w:style>'
        '<w:style w:type="paragraph" w:styleId="Bullet"><w:name w:val="Bullet"/><w:pPr><w:spacing w:after="60"/>'
        '<w:ind w:left="300" w:hanging="300"/></w:pPr></w:style>'
        '<w:style w:type="paragraph" w:styleId="Note"><w:name w:val="Note"/><w:pPr><w:spacing w:after="40"/></w:pPr>'
        '<w:rPr><w:color w:val="475569"/><w:sz w:val="17"/></w:rPr></w:style>'
        '</w:styles>')
    content_types = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/>'
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
        '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'
        '<Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/>'
        '</Types>')
    rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" '
        'Target="word/document.xml"/></Relationships>')
    doc_rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
        '<Relationship Id="rIdFooter" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/>'
        + ''.join(f'<Relationship Id="rIdFigure{i}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" '
                  f'Target="media/figure{i}.png"/>' for i in range(1, len(media) + 1)) + '</Relationships>')
    with zipfile.ZipFile(path, 'w', compression=zipfile.ZIP_DEFLATED) as archive:
        for name, text in {'[Content_Types].xml': content_types, '_rels/.rels': rels, 'word/document.xml': document,
                           'word/styles.xml': styles, 'word/footer1.xml': footer, 'word/_rels/document.xml.rels': doc_rels}.items():
            archive.writestr(name, text.encode('utf-8'))
        for i, png in enumerate(media, 1):
            archive.writestr(f'word/media/figure{i}.png', png)


def _write_explanations_docx_stdlib(project:Project,groups:list[GroupResult],path):
    """Produce a real, readable DOCX without python-docx (pure standard library).

    Eager 300 lab computers may be offline or lack extra Python packages. This
    fallback keeps Excel + project exports working while recording the same
    scientific calculations, source warnings and QC as the rich Word writer.
    """
    groups = compute_results(project, reporting=True)
    from xml.sax.saxutils import escape as xe

    def clean(value):
        txt = str(value) if value is not None else ''
        return xe(''.join(c for c in txt if c in '\t\n\r' or ord(c)>=32))

    body=[]
    def para(value='',style='Normal'):
        body.append('<w:p><w:pPr><w:pStyle w:val="'+style+'"/></w:pPr>'
                    '<w:r><w:t xml:space="preserve">'+clean(value)+'</w:t></w:r></w:p>')
    def heading(value,level=1):para(value,'Heading'+str(level))
    def bullet(value):para('•  '+str(value),'Normal')
    def table(headers,records):
        widths=[1800]*len(headers)
        grid=''.join('<w:gridCol w:w="'+str(w)+'"/>' for w in widths)
        cells=[]
        for row_i,row in enumerate([list(headers)]+[list(r) for r in records]):
            cols=[]
            for content in row:
                shading='<w:shd w:val="clear" w:fill="20334B"/>' if row_i==0 else ''
                bold='<w:rPr><w:b/><w:color w:val="FFFFFF"/></w:rPr>' if row_i==0 else ''
                cols.append('<w:tc><w:tcPr>'+shading+'</w:tcPr><w:p><w:r>'+bold+
                            '<w:t xml:space="preserve">'+clean(content)+'</w:t></w:r></w:p></w:tc>')
            cells.append('<w:tr>'+''.join(cols)+'</w:tr>')
        border='<w:top w:val="single" w:sz="4"/><w:left w:val="single" w:sz="4"/>'
        border+='<w:bottom w:val="single" w:sz="4"/><w:right w:val="single" w:sz="4"/>'
        border+='<w:insideH w:val="single" w:sz="4"/><w:insideV w:val="single" w:sz="4"/>'
        body.append('<w:tbl><w:tblPr><w:tblBorders>'+border+'</w:tblBorders></w:tblPr>'+
                    '<w:tblGrid>'+grid+'</w:tblGrid>'+''.join(cells)+'</w:tbl>')

    para('CHNSetti — detailed explanations','Title')
    para(f'{project.settings.run_name}  |  {APP_NAME} {APP_VERSION}  |  {utc_now()}')
    para(APP_DEVELOPER)
    heading('1. Scope and data origin')
    readiness=report_readiness(project)
    para('Report status: '+readiness['status'])
    for blocker in readiness['blockers']:para('Review needed: '+blocker)
    para('CHNSetti uses saved instrument results or identified spreadsheet inputs. A reviewer must verify '
         'the selected processing state, sample roles and any revised source before a reviewed final export.')
    para('Selecting a .MTH opens its sequence and identity-matched DAT detector records. Native processing can propose intervals and baselines, fit calibration standards, and calculate concentrations. The visual editor supports boundary/baseline changes, comparison with saved processing and explicitly reviewed zeros. Original signals and saved results remain intact. Numerical checks do not establish independent analytical validation.')
    para(f'Input: {project.source_name}. Format: {project.input_format}. Original input SHA-256: '
         f'{project.source_sha256}.')
    for source in project.source_files:
        para('Source file: '+source.get('role','')+' — '+source.get('name','')+'; SHA-256: '+source.get('sha256',''))
    if project.derived_from_report:
        para('WARNING: This source is a historical completed report, not an instrument export. '
             'The original standards, bypasses and chromatogram details are unavailable.')
    for warn in project.input_warnings:para('Input note: '+warn)
    heading('2. Exact calculation rules')
    for statement in [
        'The three typical replicates are separate weighed portions and separate combustions, not repeated detector readings of one tin cup.',
        'For each element N, C, H, S separately, report accepted numerical results from original measurements, approved independent revisions, valid approved reference corrections, or explicit reported-zero decisions. Also report an eligible saved unquantified numerical zero as 0 under the fixed saved-zero convention. These same numeric values enter the reported mean, SD and n; the final result table omits the n row, while technical outputs retain n reported.',
        'Arithmetic mean x̄ = (x1 + ... + xn) / n.',
        'Sample standard deviation s = sqrt(sum((xi - x̄)^2)/(n - 1)) for n ≥ 2, the Excel STDEV.S convention.',
        'Relative standard deviation RSD (%) = 100 × s / |x̄| for a nonzero mean.',
        'No automatic outlier correction is performed. When CHNSetti integrations are applied, the default choice of standards '
        'of the calibration step may leave out a standard: for each element the choice (at least two standards kept) that '
        'brings the check material closest to its certificate, when that result is within ±10 % of the certificate and at least '
        'a quarter closer than with all standards; each such exclusion is recorded with its reason. Review, derived, excluded, below-limit, missing and conflicted inputs remain withheld. Positive source values are never automatically zeroed. Eligible saved unquantified zeros use the saved-zero convention. A reporting zero selected after visual review has its own recorded reason; the original signal and original percentage remain intact. An unassigned channel otherwise remains unresolved. Missing files and ambiguous identities never supply numerical zeros.',
        'All-zero sample portions require source review or a genuine replacement and are not accepted by the saved-zero report convention. A quantified zero is numerical. An eligible saved unquantified zero is displayed as 0 and contributes to reported n, mean and SD while its source value, unquantified status and accepted n remain unchanged. Explicit reviewed reported-zero decisions retain their own review trail. Neither reporting convention establishes quantification or a detection limit.',
        'Report convention IDs: ' + REPORT_CONVENTION_ID + '; ' + NATIVE_ZERO_CONVENTION_ID + '. The detailed measurement review lists accepted and reported values side by side; report statistics always use the displayed numeric values.',
        'Spreadsheet formulas in measurement cells are derived inputs, not independent replicates. Formula text and cached values are preserved without execution.',
        'Individual sample mass (mg) is retained as provenance. It is not used to rescale the instrument-reported % w/w.',
        'Calibration standard rows (STD) can contain assigned concentrations. They are not treated as independent recovery measurements.',
        'Check materials measured as unknowns can be compared against an explicitly selected reference table; no acceptance tolerance is assumed. The Check references diagnostic sheet and reference-correction eligibility use uncorrected accepted check values. Reported check summaries, when included, follow the same saved-zero report convention as samples; a reporting zero does not become an eligible quantified check measurement.',
        'Output raw percentages use eight decimal places, mean four, SD five, and weight three, as in the observed laboratory Excel workflow.',
    ]: bullet(statement)
    heading('3. Optional reference correction')
    correction = _correction_export_context(project)
    para(correction['status'])
    para('Correction is optional and requires an explicit reference source, measured-check selection, '
         'reviewer and reason. Corrected result = source base + applied offset; the configured offset '
         'is the selected reference minus the arithmetic mean of explicitly selected eligible measured checks. '
         'The applied offset is zero for a preserved zero and absent for a held source. Calibration STD '
         'assigned values cannot serve as independent measured checks.')
    para('Original imported values and independent revisions remain preserved. Correction does not '
         'replace baseline correction, peak integration or calibration in the instrument software. '
         'No automatic clipping, normalization, detection-limit assignment or replacement to improve '
         'replicate agreement is performed. Invalid or stale corrected values are withheld for review.')
    para(correction['zero_text'])
    para('The saved-zero report convention is separate from the correction zero policy. An eligible '
         'unquantified saved zero can be reported as 0 while its correction outcome remains held_source; '
         'no reference offset is applied to that unquantified source.')
    para('An offset applied equally to every included portion preserves sample SD. A policy that '
         'preserves only some zeros can change SD; the selected policy and per-element outcomes '
         'remain part of the calculation record.')
    if correction['profile']:
        profile = correction['profile']
        selected_cfg = correction['configuration']
        para('Profile ID: ' + str(profile.get('profile_id', '')))
        para('Material: ' + str(selected_cfg.get('material', '')) + '; reference label/source: ' +
             str(selected_cfg.get('reference_label', '')))
