    def state_label(record, element):
        return measurement_status_label(record, element)

    def compact_native_info(info):
        """Describe large detector vectors without flooding source detail panels."""
        return native_metadata_summary(info)

    def reported_zero_description(record, element):
        convention = report_value_convention(record, element)
        if convention:
            return convention
        if record.values.get(element) is None:
            return ('No assigned element peak in the validated DAT; reported as 0 under the laboratory '
                    'convention. The original unquantified status is retained.')
        return 'Saved numerical zero included as 0; original unquantified status retained.'

    def origin_description(record, element):
        source = record.source_sheet or 'Source record'
        cell = record.source_cells.get(element, '')
        if cell:
            source += '!' + str(cell)
        elif record.source_row:
            source += ' / row ' + str(record.source_row)
        parts = [source]
        formula = record.formulas.get(element)
        if formula:
            parts.append('Original formula: ' + str(formula))
        text = record.source_text.get(element)
        if text and optional_number(text) is None:
            parts.append('Original text: ' + str(text))
        revision = record.revisions.get(element)
        if revision:
            parts.append('Revision record: ' + json.dumps(revision, ensure_ascii=False, default=str))
        correction = record.corrections.get(element)
        if correction:
            parts.append('Reference correction: ' + json.dumps(correction, ensure_ascii=False, default=str))
        decision = record.review_notes.get(element)
        if decision:
            parts.append('Review: ' + json.dumps(decision, ensure_ascii=False, default=str))
        if record.dat_info:
            parts.append('Saved .DAT record: ' + json.dumps(compact_native_info(record.dat_info), ensure_ascii=False, default=str))
        if record.review_flags:
            parts.append('Identity/source flags: ' + '; '.join(map(str, record.review_flags)))
        return '\n'.join(parts)

    def measurement_description(record,element,technical=False):
        if technical:return origin_description(record,element)
        parts=[f"Original value: {num(record.values.get(element),8) or '—'} %.",
               f"Selected source value: {num(source_value(record,element),8) or '—'} %.",
               f"Reported value: {report_value_text(record,element,dp=8)} %.",
               'Source state: '+state_label(record,element)+'.']
        if measurement_state(record,element)=='unquantified' and report_value(record,element)==0:
            parts.append(reported_zero_description(record, element))
        note=record.review_notes.get(element) or {}
        if note:
            parts.append('Recorded reason: '+str(note.get('reason') or 'See advanced source details')+
                         ('; reviewer '+str(note['reviewer']) if note.get('reviewer') else ''))
        correction=record.corrections.get(element) or {}
        if correction:
            parts.append('Reference correction: '+readable_outcome(correction.get('outcome','recorded'))+'.')
        source=record.source_sheet or 'Source record'
        if record.source_cells.get(element):source+=' — '+str(record.source_cells[element])
        elif record.source_row:source+=' — row '+str(record.source_row)
        parts.append(source)
        parts.append('Enable advanced source decisions to inspect the full technical source record.')
        return '\n'.join(parts)

    class MeasurementReviewDialog(QDialog):
        """One row per element allows a single decision to cover selected results."""
        def __init__(self, project, parent=None, advanced=False):
            super().__init__(parent)
            self.project = project
            self.setWindowTitle('Review measurement validity')
            self.resize(1120, 740)
            outer = QVBoxLayout(self)
            outer.addWidget(caption('Select one or several element rows, choose a decision, and record a shared '
                'reviewer and reason. Original values remain available in the project and detailed workbook. '
                'Use Ctrl or Shift to select several rows.'))
            filters = QHBoxLayout()
            self.attention = QCheckBox('Unresolved results only')
            self.attention.setChecked(True)
            self.attention.toggled.connect(self.refresh)
            filters.addWidget(self.attention)
            filters.addStretch(1)
            all_button = QPushButton('Select all visible')
            all_button.clicked.connect(lambda: self.table.selectAll())
            filters.addWidget(all_button)
            outer.addLayout(filters)
            self.advanced_choices = QCheckBox('Show advanced source decisions')
            self.advanced_choices.setChecked(advanced)
            outer.addWidget(self.advanced_choices)
            self.table = QTableWidget()
            set_table(self.table, ['#', 'Portion', 'Element', 'Original %', 'Reported %', 'Source status', 'Recorded information'], (1, 6))
            self.table.setSelectionMode(QAbstractItemView.ExtendedSelection)
            self.table.setMinimumHeight(310)
            self.table.itemSelectionChanged.connect(self.show_detail)
            outer.addWidget(self.table, 1)
            self.detail = QTextEdit()
            self.detail.setReadOnly(True)
            self.detail.setMaximumHeight(120)
            outer.addWidget(self.detail)
            decision_row = QHBoxLayout()
            decision_row.addWidget(QLabel('Apply to selected rows:'))
            self.decision = QComboBox()
            self.advanced_choices.toggled.connect(self.populate_decisions)
            self.populate_decisions()
            decision_row.addWidget(self.decision, 1)
            outer.addLayout(decision_row)
            identity_row = QHBoxLayout()
            identity_row.addWidget(quiet_label('Reviewer:'))
            self.reviewer = reviewer_edit(self)
            self.reviewer.setPlaceholderText('Name or laboratory initials')
            identity_row.addWidget(self.reviewer)
            identity_row.addWidget(QLabel('Note (optional):'))
            self.reason = QLineEdit()
            self.reason.setPlaceholderText('Evidence supporting this decision')
            identity_row.addWidget(self.reason, 2)
            outer.addLayout(identity_row)
            self.feedback = caption('The final report already includes eligible saved zeros as 0. No extra zero decision '
                'is needed for the report. Advanced source decisions can record an explicit convention in the '
                'accepted-value diagnostics; the original values and earlier decisions remain available.')
            outer.addWidget(self.feedback)
            buttons = QHBoxLayout()
            buttons.addStretch(1)
            apply_button = QPushButton('Apply to selected results')
            apply_button.clicked.connect(self.apply_selected)
            buttons.addWidget(apply_button)
            close_button = QPushButton('Close')
            close_button.clicked.connect(self.accept)
            buttons.addWidget(close_button)
            outer.addLayout(buttons)
            self.visible_rows = []
            self.advanced_choices.toggled.connect(self.refresh)
            self.refresh()

        def populate_decisions(self, *_):
            previous = self.decision.currentData()
            self.decision.clear()
            choices = [('review', 'Hold for review'), ('measured', 'Accept original measured value'),
                       ('revised', 'Use existing approved revision'), ('excluded', 'Exclude with recorded reason'),
                       ('unquantified', 'No quantified result'), ('below_limit', 'Below reporting limit')]
            if self.advanced_choices.isChecked():
                choices.append(('reported_zero', 'Record explicit zero convention in source diagnostics'))
            for state, label in choices:
                self.decision.addItem(label, state)
            found = self.decision.findData(previous)
            if found >= 0:
                self.decision.setCurrentIndex(found)

        def refresh(self, *_):
            self.table.setRowCount(0)
            self.visible_rows = []
            for record in self.project.records:
                if record.role not in ('Sample', 'Check'):
                    continue
                for element in ELEMENTS:
                    state = measurement_state(record, element)
                    if self.attention.isChecked() and not measurement_needs_decision(record, element):
                        continue
                    i = self.table.rowCount()
                    self.table.insertRow(i)
                    self.visible_rows.append((record.index, element))
                    provenance = measurement_description(record,element,technical=self.advanced_choices.isChecked())
                    note = record.review_notes.get(element) or {}
                    correction = record.corrections.get(element) or {}
                    summary = (str(note.get('reason', '')) + (' — '+str(note.get('reviewer')) if note.get('reviewer') else '')
                               if note else 'Reference correction: '+readable_outcome(correction.get('outcome', 'recorded'))
                               if correction else 'Formula-derived source' if record.formulas.get(element)
                               else 'Saved zero reported as 0; original source state retained'
                               if measurement_state(record,element)=='unquantified' and report_value(record,element)==0
                               else str(record.source_cells.get(element) or ''))
                    for col, value in enumerate((record.index, record.name, element,
                            num(record.values.get(element), 8), report_value_text(record, element, dp=8),
                            state_label(record, element), summary)):
                        item = row_item(value)
                        item.setToolTip(provenance)
                        if col == 5 and measurement_needs_decision(record, element):
                            item.setBackground(QBrush(QColor('#FEE2E2')))
                        self.table.setItem(i, col, item)
            if self.table.rowCount():
                self.table.selectRow(0)
            else:
                self.detail.setPlainText('No results match this filter. Clear the checkbox to review all measured results.')

        def show_detail(self):
            i = self.table.currentRow()
            if i < 0 or i >= len(self.visible_rows):
                return
            index, element = self.visible_rows[i]
            record = next(r for r in self.project.records if r.index == index)
            self.detail.setPlainText(f'{record.name} — {element}\n' +
                                     measurement_description(record,element,technical=self.advanced_choices.isChecked()))

        def apply_selected(self):
            rows = sorted({item.row() for item in self.table.selectedItems()})
            if not rows:
                alert(self, 'No results selected', 'Select at least one element row.', True)
                return
            reviewer, reason = self.reviewer.text().strip(), self.reason.text().strip()
            edits = [{'index': self.visible_rows[i][0], 'element': self.visible_rows[i][1],
                      'state': self.decision.currentData()} for i in rows]
            try:
                apply_measurement_reviews(self.project, edits, reviewer=reviewer, reason=reason)
            except Exception as exc:
                alert(self, 'Review not applied', str(exc), True)
                return
            self.feedback.setText(f'Recorded {len(edits)} element decisions. The original values are preserved.')
            self.refresh()

