            outer=QVBoxLayout()
            outer.setContentsMargins(0,0,0,0)
            outer.addWidget(area)
            self.setLayout(outer)
            # As in Plasmatti: the subtitle says what the page is for; the help row says what to do.
            help_row(self.layout_,self,instruction,title+' — instructions',description)
