    class ImportPage(BasePage):
        def __init__(self):
            super().__init__('Step 1 of 7: Files',
                'Choose the run to process.',
                'Open the .MTH file of the run. Its .DAT detector files are found automatically.',
                'Select the .MTH file as the starting point. CHNSetti reads the .DAT detector records identified by the '
                'method from the same run folder. If only the method is available, the sequence and stored coefficients '
                'can still be inspected; missing measurements remain uncalculated and are never filled with zero.\n'
                'More import options: a processed .SUM (saved percentages), a run folder, a run inside a ZIP archive, '
                'an Excel/CSV export, the results source used for the next import, and demonstration data.\n'
                'Saved CHNSetti projects include a measurement snapshot and can be reopened without the original folder. '
                'Original instrument files are never modified.')
            frame,v=card('Open')
            self.native_mode=QComboBox(self)
            self.native_mode.addItem('Automatic — .MTH and detector .DAT files','auto')
            self.native_mode.addItem('Saved DAT results — .MTH + .DAT','saved_dat')
            self.native_mode.addItem('Processed summary — .SUM','summary')
            self.native_mode.setToolTip('This choice applies to the next import. Saved DAT results uses the '
                                       'stored peak results, with independent method/trace checks.')
            self.native_mode.hide()
            buttons=QHBoxLayout()
            self.file_button=QPushButton('Open .MTH run')
            self.file_button.clicked.connect(self.choose_file)
            buttons.addWidget(self.file_button)
            saved=QPushButton('Open saved project')
            saved.clicked.connect(self.open_saved)
            buttons.addWidget(saved)
            self.more=QToolButton()
            self.more.setText('More import options')
            self.more.setPopupMode(QToolButton.InstantPopup)
            menu=QMenu(self.more)
            menu.addAction('Open processed .SUM…',self.choose_summary)
            menu.addAction('Open a run folder…',self.choose_folder)
            menu.addAction('Choose a run from ZIP…',self.choose_archive)
            menu.addAction('Open Excel / CSV…',self.choose_spreadsheet)
            source_menu=menu.addMenu('Results source for next import')
            self.source_actions=[]
            for index in range(self.native_mode.count()):
                action=source_menu.addAction(self.native_mode.itemText(index))
                action.setCheckable(True);action.setChecked(index==0)
                action.triggered.connect(lambda checked=False,idx=index:self.choose_source_mode(idx))
                self.source_actions.append(action)
            self.native_mode.currentIndexChanged.connect(self.source_mode_changed)
            menu.addSeparator()
            demos=menu.addMenu('Demonstration (synthetic data)')
            demos.addAction('Full run with detector signals',self.load_full_demo)
            demos.addAction('File repair: two data files swapped',lambda:self.load_full_demo(repair=True))
            demos.addAction('Results table only (no detector signals)',self.load_demo)
            self.more.setMenu(menu)
            buttons.addWidget(self.more)
            buttons.addStretch(1)
            v.addLayout(buttons)
            self.source_mode_note=caption('')
            self.source_mode_note.setVisible(False)
            v.addWidget(self.source_mode_note)
            self.source=QLabel('No file selected.')
            self.source.setWordWrap(True)
            self.source.setTextInteractionFlags(Qt.TextSelectableByMouse)
            self.source.setStyleSheet('color:#1F2937; font-weight:600; background:transparent; border:0;')
            v.addWidget(self.source)
