            self.exclude_point=QPushButton('Exclude selected point');self.exclude_point.clicked.connect(lambda:self.change_calibration_point(False));row.addWidget(self.exclude_point)
            self.include_point=QPushButton('Include selected point');self.include_point.clicked.connect(lambda:self.change_calibration_point(True));row.addWidget(self.include_point);box.addLayout(row)
            self.cal_note=QLabel();self.cal_note.setWordWrap(True);self.cal_note.setMinimumHeight(35);box.addWidget(self.cal_note)
            box.setSizeConstraint(QLayout.SetMinimumSize)
