        def _run_preview(self,automatic):
            progress=QProgressDialog('Integrating standards and samples; recalculating dependent results…','',0,0,self)
            progress.setCancelButton(None);progress.setWindowModality(Qt.WindowModal);progress.setMinimumDuration(0);progress.show();QApplication.processEvents()
            self.auto_button.setEnabled(False);self.saved_button.setEnabled(False)
