        def refresh_all(self):
            self.record_selected();self.refresh_calibration();self._update_buttons()
            counts=Counter()
            for row in (self.preview or {}).get('records',{}).values():
                for result in row.get('elements',{}).values():counts[str(result.get('status','unavailable'))]+=1
            if self.preview:
                parts=[f'{value} {name.replace("_"," ")}' for name,value in sorted(counts.items())]
                self.run_summary.setText('Preview: '+', '.join(parts)+'. Review flagged calculations before applying. '
                    'Previously applied percentage offsets are not added again.')
            else:self.run_summary.setText('No processing preview has been built. Imported results are still selected.')
        def record_selected(self,*_):
            record=next((r for r in self.project.records if r.index==self.record_combo.currentData()),None)
            if self.current_record is not None and record is not None and record.index!=self.current_record.index and (self._numeric_dirty or self._assignment_dirty):
                self.record_combo.blockSignals(True);self.record_combo.setCurrentIndex(self.record_combo.findData(self.current_record.index));self.record_combo.blockSignals(False)
                alert(self,'Record or reset interval edits','Press Recalculate interval to keep the current interval or assignment edits, or Reset controls to discard them, before selecting another measurement.');return
            self.current_record=record
            self.previous_button.setEnabled(self.record_combo.currentIndex()>0);self.next_button.setEnabled(self.record_combo.currentIndex()+1<self.record_combo.count())
            if record is None:return
            info=record.dat_info or {};trace=info.get('native_trace') or {};self.current_trace=trace
            self.current_calibration=info.get('calibration') or native_calibration_details(trace,info.get('method_info') or {})
            self.record_summary.setText(f'{record.name}  |  {record.role}  |  Mass {self.precise(record.weight_mg)} mg  |  {record.date} {record.time}'.strip())
            unsafe=info.get('status') in ('identity_mismatch','ambiguous','unsupported','missing')
            if trace.get('signal') and not native_match_record(trace,record).get('matches'):unsafe=True
            if unsafe:self.status_note.setText('This DAT is unavailable or not safely associated with this sequence row. Editing and applying its candidate trace is disabled. '+str(info.get('reason') or ''))
            elif not trace.get('signal'):self.status_note.setText('No verified detector signal is available. The method metadata can be inspected; missing measurements remain unavailable.')
            elif self.preview:self.status_note.setText('Preview — not in the report until Apply. Shaded: proposed integration. Dashed gray: integration saved by the instrument software.')
            else:self.status_note.setText('Instrument integration. Choose “Start from saved boundaries” to edit it, or propose automatic processing under Calibration and processing.')
            self.plot.set_trace(trace)
            self.saved_peak_combo.blockSignals(True);self.saved_peak_combo.clear()
            for peak in trace.get('peaks') or []:self.saved_peak_combo.addItem(f"{peak.get('index')} · {peak.get('element') or 'Unassigned'} · {peak.get('start')}–{peak.get('end')}",peak.get('index'))
            self.saved_peak_combo.blockSignals(False)
            self._editable_record=bool(trace.get('signal') and not unsafe)
            self.element_selected()
        def element_selected(self,*_):
            if self.current_record is None:return
